    } catch (error) {
        console.error('Update notification template error:', error);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// DELETE /api/admin/registration/notification-templates/{template_id} - Delete template
app.delete('/api/admin/registration/notification-templates/:template_id', authenticateAdmin, async (req, res) => {
    const { template_id } = req.params;

    try {
        // Validate template_id (UUID format)
        if (!template_id || !template_id.match(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i)) {
            return res.status(400).json({ error: 'Valid template ID is required' });
        }

        // Check if template exists
        const { data: template, error: fetchError } = await supabase
            .from('notification_templates')
            .select('id, name')
            .eq('id', template_id)
            .single();

        if (fetchError) {
            if (fetchError.code === 'PGRST116') {
                return res.status(404).json({ error: 'Notification template not found' });
            }
            console.error('Template fetch error:', fetchError);
            return res.status(500).json({ error: 'Failed to fetch notification template' });
        }

        // Delete the template
        const { error: deleteError } = await supabase
            .from('notification_templates')
            .delete()
            .eq('id', template_id);

        if (deleteError) {
            console.error('Template deletion error:', deleteError);
            return res.status(500).json({ error: 'Failed to delete notification template' });
        }

        res.status(204).send(); // No content response
    } catch (error) {
        console.error('Delete notification template error:', error);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// POST /api/admin/registration/send-notification - Send notification using template
app.post('/api/admin/registration/send-notification', authenticateAdmin, async (req, res) => {
    const { template_id, recipient_type, recipient_id, placeholders = {} } = req.body;

    try {
        // Validate required fields
        if (!template_id || !template_id.match(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i)) {
            return res.status(400).json({ error: 'Valid template ID is required' });
        }

        if (!recipient_type || !['player', 'user', 'email'].includes(recipient_type)) {
            return res.status(400).json({
                error: 'Valid recipient type is required',
                valid_types: ['player', 'user', 'email']
            });
        }

        if (!recipient_id) {
            return res.status(400).json({ error: 'Recipient ID is required' });
        }

        if (typeof placeholders !== 'object' || Array.isArray(placeholders)) {
            return res.status(400).json({ error: 'Placeholders must be an object' });
        }

        // Fetch the template
        const { data: template, error: templateError } = await supabase
            .from('notification_templates')
            .select('*')
            .eq('id', template_id)
            .eq('is_active', true)
            .single();

        if (templateError) {
            if (templateError.code === 'PGRST116') {
                return res.status(404).json({ error: 'Active notification template not found' });
            }
            console.error('Template fetch error:', templateError);
            return res.status(500).json({ error: 'Failed to fetch notification template' });
        }

        // Get recipient information
        let recipientEmail = null;
        let recipientName = null;

        if (recipient_type === 'player') {
            const { data: player, error: playerError } = await supabase
                .from('players')
                .select('email, first_name, last_name, player_email')
                .eq('id', recipient_id)
                .single();

            if (playerError) {
                if (playerError.code === 'PGRST116') {
                    return res.status(404).json({ error: 'Player not found' });
                }
                console.error('Player fetch error:', playerError);
                return res.status(500).json({ error: 'Failed to fetch player information' });
            }

            recipientEmail = player.player_email || player.email;
            recipientName = `${player.first_name} ${player.last_name}`;
        } else if (recipient_type === 'user') {
            const { data: user, error: userError } = await supabase
                .from('users')
                .select('email, first_name, last_name')
                .eq('id', recipient_id)
                .single();

            if (userError) {
                if (userError.code === 'PGRST116') {
                    return res.status(404).json({ error: 'User not found' });
                }
                console.error('User fetch error:', userError);
                return res.status(500).json({ error: 'Failed to fetch user information' });
            }

            recipientEmail = user.email;
            recipientName = `${user.first_name} ${user.last_name}`;
        } else if (recipient_type === 'email') {
            recipientEmail = recipient_id;
            recipientName = 'Recipient';
        }

        if (!recipientEmail) {
            return res.status(400).json({ error: 'Recipient email not found or invalid' });
        }

        // Substitute placeholders in template content
        const substituePlaceholders = (text, placeholderValues) => {
            if (!text) return text;

            let substituted = text;

            // Built-in placeholders
            const builtInPlaceholders = {
                '{recipient_name}': recipientName || 'Recipient',
                '{recipient_email}': recipientEmail,
                '{current_date}': new Date().toLocaleDateString(),
                '{current_time}': new Date().toLocaleTimeString()
            };

            // Apply built-in placeholders
            Object.entries(builtInPlaceholders).forEach(([placeholder, value]) => {
                substituted = substituted.replace(new RegExp(placeholder.replace(/[{}]/g, '\\$&'), 'g'), value);
            });

            // Apply custom placeholders
            Object.entries(placeholderValues).forEach(([key, value]) => {
                const placeholder = `{${key}}`;
                substituted = substituted.replace(new RegExp(placeholder.replace(/[{}]/g, '\\$&'), 'g'), value || '');
            });

            return substituted;
        };

        const processedSubject = template.subject ? substituePlaceholders(template.subject, placeholders) : null;
        const processedBody = substituePlaceholders(template.body, placeholders);

        // Since email/SMS service integration is out of scope, simulate sending
        const notificationResult = {
            template_id: template.id,
            template_name: template.name,
            type: template.type,
            recipient: {
                type: recipient_type,
                id: recipient_id,
                email: recipientEmail,
                name: recipientName
            },
            processed_content: {
                subject: processedSubject,
                body: processedBody
            },
            status: 'simulated', // Would be 'sent', 'failed', etc. with real integration
            sent_at: new Date().toISOString(),
            message: 'Notification sending simulated (email/SMS service integration not implemented)'
        };

        res.json({
            message: 'Notification processed successfully',
            result: notificationResult
        });
    } catch (error) {
        console.error('Send notification error:', error);
        res.status(500).json({ error: 'Internal server error' });
    }
});

// Report Endpoints

tool_input.content:
import { useEffect, useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Settings, Edit, Users, Calendar, AlertCircle, CheckCircle, RefreshCw, ArrowLeft } from 'lucide-react'
import { Button } from './ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from './ui/card'
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from './ui/dialog'
import { Input } from './ui/input'
import { useApi } from '../hooks/useApi'

interface Program {
  id: string
  name: string
  description?: string
  season?: string
  start_date: string
  end_date: string
  registration_open_date: string
  registration_close_date: string
  max_capacity?: number
  base_fee: number
  is_active: boolean
  created_at: string
  updated_at: string
  current_registrations?: number
  available_spots?: number
}

interface ProgramCapacity {
  program_id: string
  program_name: string
  current_registrations: number
  max_capacity: number | null
  available_spots: number | null
  is_full: boolean
  capacity_utilization: number | null
}

interface EditFormData {
  max_capacity: string
  registration_open_date: string
  registration_close_date: string
  is_active: boolean
}

interface ProgramSettingsManagementProps {
  onBack: () => void
}

const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.1
    }
  }
}

const itemVariants = {
  hidden: { y: 20, opacity: 0 },
  visible: {
    y: 0,
    opacity: 1,
    transition: {
      duration: 0.3
    }
  }
}

export default function ProgramSettingsManagement({ onBack }: ProgramSettingsManagementProps) {
  const [programs, setPrograms] = useState<Program[]>([])
  const [capacityData, setCapacityData] = useState<Record<string, ProgramCapacity>>({})
  const [editingProgram, setEditingProgram] = useState<Program | null>(null)
  const [editFormData, setEditFormData] = useState<EditFormData>({
    max_capacity: '',
    registration_open_date: '',
    registration_close_date: '',
    is_active: true
  })
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null)
  const [formErrors, setFormErrors] = useState<Record<string, string>>({})
  const [isSubmitting, setIsSubmitting] = useState(false)

  const { loading: programsLoading, execute } = useApi()

  useEffect(() => {
    fetchPrograms()
  }, [])

  const fetchPrograms = async () => {
    try {
      const response = await execute('/api/programs')
      if (response?.programs) {
        setPrograms(response.programs)
        // Fetch capacity data for each program
        fetchCapacityData(response.programs)
      }
    } catch (error) {
      console.error('Error fetching programs:', error)
      setMessage({ type: 'error', text: 'Failed to fetch programs' })
    }
  }

  const fetchCapacityData = async (programList: Program[]) => {
    const capacityPromises = programList.map(async (program) => {
      try {
        const capacity = await execute(`/api/admin/registration/programs/${program.id}/capacity`)
        return { programId: program.id, capacity }
      } catch (error) {
        console.error(`Error fetching capacity for program ${program.id}:`, error)
        return { programId: program.id, capacity: null }
      }
    })

    const results = await Promise.all(capacityPromises)
    const capacityMap: Record<string, ProgramCapacity> = {}

    results.forEach(({ programId, capacity }) => {
      if (capacity) {
        capacityMap[programId] = capacity
      }
    })

    setCapacityData(capacityMap)
  }

  const formatDate = (dateString: string): string => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    })
  }

  const formatDateForInput = (dateString: string): string => {
    return new Date(dateString).toISOString().split('T')[0]
  }

  const validateForm = (): boolean => {
    const errors: Record<string, string> = {}

    // Validate max capacity
    if (editFormData.max_capacity.trim() !== '') {
      const capacity = parseInt(editFormData.max_capacity)
      if (isNaN(capacity) || capacity <= 0) {
        errors.max_capacity = 'Capacity must be a positive number'
      }
    }

    // Validate dates
    if (!editFormData.registration_open_date) {
      errors.registration_open_date = 'Registration open date is required'
    }

    if (!editFormData.registration_close_date) {
      errors.registration_close_date = 'Registration close date is required'
    }

    if (editFormData.registration_open_date && editFormData.registration_close_date) {
      const openDate = new Date(editFormData.registration_open_date)
      const closeDate = new Date(editFormData.registration_close_date)

      if (openDate >= closeDate) {
        errors.registration_close_date = 'Close date must be after open date'
      }
    }

    setFormErrors(errors)
    return Object.keys(errors).length === 0
  }

  const openEditModal = (program: Program) => {
    setEditingProgram(program)
    setEditFormData({
      max_capacity: program.max_capacity?.toString() || '',
      registration_open_date: formatDateForInput(program.registration_open_date),
      registration_close_date: formatDateForInput(program.registration_close_date),
      is_active: program.is_active
    })
    setFormErrors({})
    setMessage(null)
  }

  const closeEditModal = () => {
    setEditingProgram(null)
    setEditFormData({
      max_capacity: '',
      registration_open_date: '',
      registration_close_date: '',
      is_active: true
    })
    setFormErrors({})
    setMessage(null)
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!editingProgram || !validateForm()) {
      return
    }

    setIsSubmitting(true)
    setMessage(null)

    try {
      const updateData: any = {
        registration_open_date: editFormData.registration_open_date,
        registration_close_date: editFormData.registration_close_date,
        is_active: editFormData.is_active
      }

      if (editFormData.max_capacity.trim() !== '') {
        updateData.max_capacity = parseInt(editFormData.max_capacity)
      } else {
        updateData.max_capacity = null
      }

      const response = await execute(`/api/admin/registration/programs/${editingProgram.id}/settings`, {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(updateData)
      })

      if (response) {
        setMessage({ type: 'success', text: 'Program settings updated successfully' })

        // Refresh programs list
        await fetchPrograms()

        // Close modal after a brief delay
        setTimeout(() => {
          closeEditModal()
        }, 1500)
      }
    } catch (error: any) {
      console.error('Error updating program settings:', error)
      setMessage({
        type: 'error',
        text: error.message || 'Failed to update program settings'
      })
    } finally {
      setIsSubmitting(false)
    }
  }

  const clearMessage = () => {
    setMessage(null)
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <Button variant="outline" onClick={onBack} className="flex items-center space-x-2">
            <ArrowLeft className="h-4 w-4" />
            <span>Back to Dashboard</span>
          </Button>
          <div>
            <h2 className="text-2xl font-bold text-gray-900">Program Settings Management</h2>
            <p className="text-gray-600">Configure program capacity and registration dates</p>
          </div>
        </div>
        <Button
          variant="outline"
          onClick={fetchPrograms}
          disabled={programsLoading}
          className="flex items-center space-x-2"
        >
          <RefreshCw className={`h-4 w-4 ${programsLoading ? 'animate-spin' : ''}`} />
          <span>Refresh</span>
        </Button>
      </div>

      {/* Message Display */}
      <AnimatePresence>
        {message && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className={`p-4 rounded-lg border ${
              message.type === 'success'
                ? 'bg-green-50 border-green-200 text-green-800'
                : 'bg-red-50 border-red-200 text-red-800'
            }`}
          >
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-2">
                {message.type === 'success' ? (
                  <CheckCircle className="h-5 w-5" />
                ) : (
                  <AlertCircle className="h-5 w-5" />
                )}
                <span>{message.text}</span>
              </div>
              <Button variant="ghost" size="sm" onClick={clearMessage}>
                ×
              </Button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Programs List */}
      <motion.div
        variants={containerVariants}
        initial="hidden"
        animate="visible"
        className="space-y-4"
      >
        {programsLoading ? (
          <div className="flex items-center justify-center py-12">
            <RefreshCw className="h-8 w-8 animate-spin text-gray-400" />
            <span className="ml-3 text-gray-500">Loading programs...</span>
          </div>
        ) : programs.length === 0 ? (
          <Card>
            <CardContent className="flex items-center justify-center py-12">
              <div className="text-center">
                <Settings className="h-12 w-12 text-gray-400 mx-auto mb-4" />
                <h3 className="text-lg font-medium text-gray-900 mb-2">No Programs Found</h3>
                <p className="text-gray-500">Create your first program to get started.</p>
              </div>
            </CardContent>
          </Card>
        ) : (
          programs.map((program) => {
            const capacity = capacityData[program.id]

            return (
              <motion.div key={program.id} variants={itemVariants}>
                <Card className="hover:shadow-md transition-shadow">
                  <CardHeader>
                    <div className="flex items-center justify-between">
                      <div>
                        <CardTitle className="text-lg">{program.name}</CardTitle>
                        <CardDescription>
                          {program.season && `${program.season} • `}
                          {formatDate(program.start_date)} - {formatDate(program.end_date)}
                        </CardDescription>
                      </div>
                      <div className="flex items-center space-x-2">
                        <div className={`px-2 py-1 rounded-full text-xs font-medium ${
                          program.is_active
                            ? 'bg-green-100 text-green-800'
                            : 'bg-gray-100 text-gray-800'
                        }`}>
                          {program.is_active ? 'Active' : 'Inactive'}
                        </div>
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={() => openEditModal(program)}
                          className="flex items-center space-x-1"
                        >
                          <Edit className="h-4 w-4" />
                          <span>Edit Settings</span>
                        </Button>
                      </div>
                    </div>
                  </CardHeader>
                  <CardContent>
                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                      <div>
                        <label className="text-sm font-medium text-gray-600">Registration Period</label>
                        <p className="text-sm">
                          {formatDate(program.registration_open_date)} - {formatDate(program.registration_close_date)}
                        </p>
                      </div>

                      <div>
                        <label className="text-sm font-medium text-gray-600">Capacity</label>
                        <p className="text-sm">
                          {program.max_capacity ? `${program.max_capacity} spots` : 'Unlimited'}
                        </p>
                      </div>

                      <div>
                        <label className="text-sm font-medium text-gray-600">Current Registrations</label>
                        <div className="flex items-center space-x-2">
                          <Users className="h-4 w-4 text-gray-400" />
                          <span className="text-sm font-medium">
                            {capacity?.current_registrations ?? '-'}
                          </span>
                        </div>
                      </div>

                      <div>
                        <label className="text-sm font-medium text-gray-600">Available Spots</label>
                        <p className={`text-sm font-medium ${
                          capacity?.available_spots === 0 ? 'text-red-600' :
                          capacity?.available_spots && capacity.available_spots < 5 ? 'text-orange-600' :
                          'text-green-600'
                        }`}>
                          {capacity?.available_spots !== null ? capacity?.available_spots : 'Unlimited'}
                          {capacity?.is_full && ' (Full)'}
                        </p>
                      </div>
                    </div>

                    {capacity?.capacity_utilization !== null && (
                      <div className="mt-4">
                        <div className="flex items-center justify-between text-sm">
                          <span className="text-gray-600">Capacity Utilization</span>
                          <span className="font-medium">{capacity.capacity_utilization}%</span>
                        </div>
                        <div className="w-full bg-gray-200 rounded-full h-2 mt-1">
                          <div
                            className={`h-2 rounded-full transition-all ${
                              capacity.capacity_utilization >= 90 ? 'bg-red-500' :
                              capacity.capacity_utilization >= 75 ? 'bg-orange-500' :
                              'bg-green-500'
                            }`}
                            style={{ width: `${Math.min(capacity.capacity_utilization, 100)}%` }}
                          ></div>
                        </div>
                      </div>
                    )}
                  </CardContent>
                </Card>
              </motion.div>
            )
          })
        )}
      </motion.div>

      {/* Edit Modal */}
      <Dialog open={!!editingProgram} onOpenChange={closeEditModal}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Edit Program Settings</DialogTitle>
            <DialogDescription>
              Update capacity and registration dates for {editingProgram?.name}
            </DialogDescription>
          </DialogHeader>

          {/* Message in Modal */}
          <AnimatePresence>
            {message && (
              <motion.div
                initial={{ opacity: 0, y: -10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                className={`p-3 rounded-lg border text-sm ${
                  message.type === 'success'
                    ? 'bg-green-50 border-green-200 text-green-800'
                    : 'bg-red-50 border-red-200 text-red-800'
                }`}
              >
                <div className="flex items-center space-x-2">
                  {message.type === 'success' ? (
                    <CheckCircle className="h-4 w-4" />
                  ) : (
                    <AlertCircle className="h-4 w-4" />
                  )}
                  <span>{message.text}</span>
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Maximum Capacity
              </label>
              <Input
                type="number"
                placeholder="Leave empty for unlimited"
                value={editFormData.max_capacity}
                onChange={(e) => setEditFormData({ ...editFormData, max_capacity: e.target.value })}
                className={formErrors.max_capacity ? 'border-red-300' : ''}
                min="1"
              />
              {formErrors.max_capacity && (
                <p className="text-red-600 text-sm mt-1">{formErrors.max_capacity}</p>
              )}
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Registration Open Date
              </label>
              <Input
                type="date"
                value={editFormData.registration_open_date}
                onChange={(e) => setEditFormData({ ...editFormData, registration_open_date: e.target.value })}
                className={formErrors.registration_open_date ? 'border-red-300' : ''}
                required
              />
              {formErrors.registration_open_date && (
                <p className="text-red-600 text-sm mt-1">{formErrors.registration_open_date}</p>
              )}
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Registration Close Date
              </label>
              <Input
                type="date"
                value={editFormData.registration_close_date}
                onChange={(e) => setEditFormData({ ...editFormData, registration_close_date: e.target.value })}
                className={formErrors.registration_close_date ? 'border-red-300' : ''}
                required
              />
              {formErrors.registration_close_date && (
                <p className="text-red-600 text-sm mt-1">{formErrors.registration_close_date}</p>
              )}
            </div>

            <div className="flex items-center space-x-2">
              <input
                type="checkbox"
                id="is_active"
                checked={editFormData.is_active}
                onChange={(e) => setEditFormData({ ...editFormData, is_active: e.target.checked })}
                className="rounded border-gray-300"
              />
              <label htmlFor="is_active" className="text-sm font-medium text-gray-700">
                Program is active
              </label>
            </div>

            <div className="flex space-x-3 pt-4">
              <Button
                type="button"
                variant="outline"
                onClick={closeEditModal}
                disabled={isSubmitting}
                className="flex-1"
              >
                Cancel
              </Button>
              <Button
                type="submit"
                disabled={isSubmitting}
                className="flex-1"
              >
                {isSubmitting ? 'Updating...' : 'Update Settings'}
              </Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import {
  List, Users, Clock, CheckCircle, XCircle, AlertTriangle,
  Filter, Search, RefreshCw, ArrowLeft, Edit, Trash2,
  Calendar, User, ChevronLeft, ChevronRight
} from 'lucide-react'
import { Button } from './ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from './ui/card'
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from './ui/dialog'
import { Input } from './ui/input'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from './ui/select'
import { useApi } from '../hooks/useApi'

interface WaitlistEntry {
  id: string
  program_id: string
  player_id: number
  status: 'Active' | 'Offered' | 'Accepted' | 'Declined' | 'Expired'
  waitlist_date: string
  offer_expiration_date?: string
  position_in_queue?: number
  notes?: string
  created_at: string
  updated_at: string
  player: {
    id: number
    first_name: string
    last_name: string
    full_name: string
    email: string
  }
}

interface Program {
  id: string
  name: string
}

interface WaitlistManagementProps {
  onBack: () => void
}

type ModalType = 'offer' | 'status' | 'remove' | null

const statusConfig = {
  Active: { color: 'text-blue-600', bg: 'bg-blue-100', icon: Clock },
  Offered: { color: 'text-orange-600', bg: 'bg-orange-100', icon: Calendar },
  Accepted: { color: 'text-green-600', bg: 'bg-green-100', icon: CheckCircle },
  Declined: { color: 'text-red-600', bg: 'bg-red-100', icon: XCircle },
  Expired: { color: 'text-gray-600', bg: 'bg-gray-100', icon: AlertTriangle }
}

const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.05
    }
  }
}

const itemVariants = {
  hidden: { y: 20, opacity: 0 },
  visible: {
    y: 0,
    opacity: 1,
    transition: {
      duration: 0.3
    }
  }
}

export default function WaitlistManagement({ onBack }: WaitlistManagementProps) {
  const [waitlistEntries, setWaitlistEntries] = useState<WaitlistEntry[]>([])
  const [programs, setPrograms] = useState<Program[]>([])
  const [selectedProgram, setSelectedProgram] = useState<string>('all')
  const [selectedStatus, setSelectedStatus] = useState<string>('all')
  const [searchTerm, setSearchTerm] = useState('')
  const [currentPage, setCurrentPage] = useState(1)
  const [pageSize, setPageSize] = useState(20)
  const [totalPages, setTotalPages] = useState(1)
  const [totalEntries, setTotalEntries] = useState(0)
  const [loading, setLoading] = useState(false)

  // Modal states
  const [modalType, setModalType] = useState<ModalType>(null)
  const [selectedEntry, setSelectedEntry] = useState<WaitlistEntry | null>(null)
  const [offerExpirationHours, setOfferExpirationHours] = useState(48)
  const [newStatus, setNewStatus] = useState<string>('')
  const [statusNotes, setStatusNotes] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null)

  const { execute } = useApi()

  useEffect(() => {
    fetchPrograms()
    fetchWaitlistEntries()
  }, [selectedProgram, selectedStatus, currentPage, pageSize])

  const fetchPrograms = async () => {
    try {
      const response = await execute('/api/programs')
      if (response?.programs) {
        setPrograms(response.programs)
      }
    } catch (error) {
      console.error('Error fetching programs:', error)
    }
  }

  const fetchWaitlistEntries = async () => {
    if (!selectedProgram || selectedProgram === 'all') {
      // For now, we'll show message that program selection is required
      setWaitlistEntries([])
      return
    }

    setLoading(true)
    try {
      const params = new URLSearchParams({
        page: currentPage.toString(),
        limit: pageSize.toString()
      })

      if (selectedStatus !== 'all') {
        params.append('status', selectedStatus)
      }

      const response = await execute(`/api/admin/registration/programs/${selectedProgram}/waitlist?${params}`)

      if (response) {
        setWaitlistEntries(response.waitlist_entries || [])
        setTotalPages(response.pagination?.total_pages || 1)
        setTotalEntries(response.pagination?.total || 0)
      }
    } catch (error) {
      console.error('Error fetching waitlist entries:', error)
      setMessage({ type: 'error', text: 'Failed to fetch waitlist entries' })
    } finally {
      setLoading(false)
    }
  }

  const formatDate = (dateString: string): string => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  }

  const isOfferExpired = (expirationDate?: string): boolean => {
    if (!expirationDate) return false
    return new Date(expirationDate) < new Date()
  }

  const filteredEntries = waitlistEntries.filter(entry => {
    if (!searchTerm) return true
    const searchLower = searchTerm.toLowerCase()
    return (
      entry.player.full_name.toLowerCase().includes(searchLower) ||
      entry.player.email.toLowerCase().includes(searchLower)
    )
  })

  const handleOfferSpot = async () => {
    if (!selectedEntry) return

    setIsSubmitting(true)
    try {
      const response = await execute(`/api/admin/registration/waitlist/${selectedEntry.id}/offer`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ offer_expiration_hours: offerExpirationHours })
      })

      if (response) {
        setMessage({ type: 'success', text: 'Spot offered successfully' })
        closeModal()
        fetchWaitlistEntries()
      }
    } catch (error: any) {
      setMessage({ type: 'error', text: error.message || 'Failed to offer spot' })
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleUpdateStatus = async () => {
    if (!selectedEntry || !newStatus) return

    setIsSubmitting(true)
    try {
      const response = await execute(`/api/admin/registration/waitlist/${selectedEntry.id}/status`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          status: newStatus,
          notes: statusNotes.trim() || undefined
        })
      })

      if (response) {
        setMessage({
          type: 'success',
          text: `Status updated to ${newStatus}${response.registration_created ? ' and registration created' : ''}`
        })
        closeModal()
        fetchWaitlistEntries()
      }
    } catch (error: any) {
      setMessage({ type: 'error', text: error.message || 'Failed to update status' })
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleRemoveFromWaitlist = async () => {
    if (!selectedEntry) return

    setIsSubmitting(true)
    try {
      await execute(`/api/admin/registration/waitlist/${selectedEntry.id}`, {
        method: 'DELETE'
      })

      setMessage({ type: 'success', text: 'Player removed from waitlist successfully' })
      closeModal()
      fetchWaitlistEntries()
    } catch (error: any) {
      setMessage({ type: 'error', text: error.message || 'Failed to remove from waitlist' })
    } finally {
      setIsSubmitting(false)
    }
  }

  const openModal = (type: ModalType, entry: WaitlistEntry) => {
    setSelectedEntry(entry)
    setModalType(type)
    setMessage(null)

    if (type === 'offer') {
      setOfferExpirationHours(48)
    } else if (type === 'status') {
      setNewStatus(entry.status)
      setStatusNotes('')
    }
  }

  const closeModal = () => {
    setModalType(null)
    setSelectedEntry(null)
    setOfferExpirationHours(48)
    setNewStatus('')
    setStatusNotes('')
    setMessage(null)
  }

  const handlePageChange = (page: number) => {
    setCurrentPage(page)
  }

  const clearMessage = () => {
    setMessage(null)
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <Button variant="outline" onClick={onBack} className="flex items-center space-x-2">
            <ArrowLeft className="h-4 w-4" />
            <span>Back to Dashboard</span>
          </Button>
          <div>
            <h2 className="text-2xl font-bold text-gray-900">Waitlist Management</h2>
            <p className="text-gray-600">Manage program waitlists and offer spots to players</p>
          </div>
        </div>
        <Button
          variant="outline"
          onClick={fetchWaitlistEntries}
          disabled={loading}
          className="flex items-center space-x-2"
        >
          <RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
          <span>Refresh</span>
        </Button>
      </div>

      {/* Message Display */}
      <AnimatePresence>
        {message && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className={`p-4 rounded-lg border ${
              message.type === 'success'
                ? 'bg-green-50 border-green-200 text-green-800'
                : 'bg-red-50 border-red-200 text-red-800'
            }`}
          >
            <div className="flex items-center justify-between">
              <span>{message.text}</span>
              <Button variant="ghost" size="sm" onClick={clearMessage}>
                ×
              </Button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center space-x-2">
            <Filter className="h-5 w-5" />
            <span>Filters</span>
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Program</label>
              <Select value={selectedProgram} onValueChange={setSelectedProgram}>
                <SelectTrigger>
                  <SelectValue placeholder="Select program" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Programs</SelectItem>
                  {programs.map((program) => (
                    <SelectItem key={program.id} value={program.id}>
                      {program.name}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Status</label>
              <Select value={selectedStatus} onValueChange={setSelectedStatus}>
                <SelectTrigger>
                  <SelectValue placeholder="Select status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Statuses</SelectItem>
                  <SelectItem value="Active">Active</SelectItem>
                  <SelectItem value="Offered">Offered</SelectItem>
                  <SelectItem value="Accepted">Accepted</SelectItem>
                  <SelectItem value="Declined">Declined</SelectItem>
                  <SelectItem value="Expired">Expired</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Search Player</label>
              <div className="relative">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4" />
                <Input
                  placeholder="Search by name or email"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Page Size</label>
              <Select value={pageSize.toString()} onValueChange={(value) => setPageSize(parseInt(value))}>
                <SelectTrigger>
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="10">10 per page</SelectItem>
                  <SelectItem value="20">20 per page</SelectItem>
                  <SelectItem value="50">50 per page</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Waitlist Entries */}
      {selectedProgram === 'all' ? (
        <Card>
          <CardContent className="flex items-center justify-center py-12">
            <div className="text-center">
              <List className="h-12 w-12 text-gray-400 mx-auto mb-4" />
              <h3 className="text-lg font-medium text-gray-900 mb-2">Select a Program</h3>
              <p className="text-gray-500">Please select a specific program to view its waitlist entries.</p>
            </div>
          </CardContent>
        </Card>
      ) : loading ? (
        <div className="flex items-center justify-center py-12">
          <RefreshCw className="h-8 w-8 animate-spin text-gray-400" />
          <span className="ml-3 text-gray-500">Loading waitlist entries...</span>
        </div>
      ) : filteredEntries.length === 0 ? (
        <Card>
          <CardContent className="flex items-center justify-center py-12">
            <div className="text-center">
              <Users className="h-12 w-12 text-gray-400 mx-auto mb-4" />
              <h3 className="text-lg font-medium text-gray-900 mb-2">No Waitlist Entries</h3>
              <p className="text-gray-500">
                {searchTerm ? 'No entries match your search criteria.' : 'This program has no waitlist entries yet.'}
              </p>
            </div>
          </CardContent>
        </Card>
      ) : (
        <motion.div
          variants={containerVariants}
          initial="hidden"
          animate="visible"
          className="space-y-4"
        >
          {filteredEntries.map((entry) => {
            const statusInfo = statusConfig[entry.status]
            const StatusIcon = statusInfo.icon
            const isExpired = entry.status === 'Offered' && isOfferExpired(entry.offer_expiration_date)

            return (
              <motion.div key={entry.id} variants={itemVariants}>
                <Card className="hover:shadow-md transition-shadow">
                  <CardContent className="p-6">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center space-x-4">
                        <div className="flex-shrink-0">
                          <User className="h-10 w-10 text-gray-400" />
                        </div>
                        <div>
                          <h3 className="text-lg font-medium text-gray-900">
                            {entry.player.full_name}
                          </h3>
                          <p className="text-sm text-gray-500">{entry.player.email}</p>
                          <p className="text-sm text-gray-500">
                            Added: {formatDate(entry.waitlist_date)}
                          </p>
                        </div>
                      </div>

                      <div className="flex items-center space-x-4">
                        <div className="text-right">
                          <div className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${statusInfo.bg} ${statusInfo.color}`}>
                            <StatusIcon className="h-3 w-3 mr-1" />
                            {entry.status}
                            {isExpired && ' (Expired)'}
                          </div>
                          {entry.position_in_queue && (
                            <p className="text-sm text-gray-500 mt-1">
                              Position: #{entry.position_in_queue}
                            </p>
                          )}
                          {entry.offer_expiration_date && (
                            <p className={`text-sm mt-1 ${isExpired ? 'text-red-600' : 'text-gray-500'}`}>
                              Expires: {formatDate(entry.offer_expiration_date)}
                            </p>
                          )}
                        </div>

                        <div className="flex items-center space-x-2">
                          {entry.status === 'Active' && (
                            <Button
                              size="sm"
                              onClick={() => openModal('offer', entry)}
                              className="flex items-center space-x-1"
                            >
                              <Calendar className="h-4 w-4" />
                              <span>Offer Spot</span>
                            </Button>
                          )}

                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => openModal('status', entry)}
                            className="flex items-center space-x-1"
                          >
                            <Edit className="h-4 w-4" />
                            <span>Update Status</span>
                          </Button>

                          <Button
                            size="sm"
                            variant="outline"
                            onClick={() => openModal('remove', entry)}
                            className="flex items-center space-x-1 text-red-600 hover:text-red-700"
                          >
                            <Trash2 className="h-4 w-4" />
                            <span>Remove</span>
                          </Button>
                        </div>
                      </div>
                    </div>

                    {entry.notes && (
                      <div className="mt-4 p-3 bg-gray-50 rounded-lg">
                        <p className="text-sm text-gray-700">
                          <strong>Notes:</strong> {entry.notes}
                        </p>
                      </div>
                    )}
                  </CardContent>
                </Card>
              </motion.div>
            )
          })}

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="flex items-center justify-between">
              <div className="text-sm text-gray-500">
                Showing {filteredEntries.length} of {totalEntries} entries
              </div>
              <div className="flex items-center space-x-2">
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => handlePageChange(currentPage - 1)}
                  disabled={currentPage === 1}
                >
                  <ChevronLeft className="h-4 w-4" />
                  Previous
                </Button>

                <span className="text-sm text-gray-700">
                  Page {currentPage} of {totalPages}
                </span>

                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => handlePageChange(currentPage + 1)}
                  disabled={currentPage === totalPages}
                >
                  Next
                  <ChevronRight className="h-4 w-4" />
                </Button>
              </div>
            </div>
          )}
        </motion.div>
      )}

      {/* Offer Spot Modal */}
      <Dialog open={modalType === 'offer'} onOpenChange={closeModal}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Offer Spot to Player</DialogTitle>
            <DialogDescription>
              Offer a spot to {selectedEntry?.player.full_name} and set an expiration date for the offer.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Offer Expiration (hours)
              </label>
              <Input
                type="number"
                value={offerExpirationHours}
                onChange={(e) => setOfferExpirationHours(parseInt(e.target.value) || 48)}
                min="1"
                max="168"
                className="w-full"
              />
              <p className="text-sm text-gray-500 mt-1">
                Offer will expire in {offerExpirationHours} hours
              </p>
            </div>

            <div className="flex space-x-3 pt-4">
              <Button
                variant="outline"
                onClick={closeModal}
                disabled={isSubmitting}
                className="flex-1"
              >
                Cancel
              </Button>
              <Button
                onClick={handleOfferSpot}
                disabled={isSubmitting}
                className="flex-1"
              >
                {isSubmitting ? 'Offering...' : 'Offer Spot'}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      {/* Update Status Modal */}
      <Dialog open={modalType === 'status'} onOpenChange={closeModal}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Update Waitlist Status</DialogTitle>
            <DialogDescription>
              Update the status for {selectedEntry?.player.full_name}'s waitlist entry.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                New Status
              </label>
              <Select value={newStatus} onValueChange={setNewStatus}>
                <SelectTrigger>
                  <SelectValue placeholder="Select new status" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Active">Active</SelectItem>
                  <SelectItem value="Offered">Offered</SelectItem>
                  <SelectItem value="Accepted">Accepted</SelectItem>
                  <SelectItem value="Declined">Declined</SelectItem>
                  <SelectItem value="Expired">Expired</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Notes (optional)
              </label>
              <Input
                value={statusNotes}
                onChange={(e) => setStatusNotes(e.target.value)}
                placeholder="Add notes about this status change"
              />
            </div>

            {newStatus === 'Accepted' && (
              <div className="p-3 bg-green-50 border border-green-200 rounded-lg">
                <p className="text-sm text-green-800">
                  ⚠️ Setting status to "Accepted" will automatically create a program registration for this player.
                </p>
              </div>
            )}

            <div className="flex space-x-3 pt-4">
              <Button
                variant="outline"
                onClick={closeModal}
                disabled={isSubmitting}
                className="flex-1"
              >
                Cancel
              </Button>
              <Button
                onClick={handleUpdateStatus}
                disabled={isSubmitting || !newStatus}
                className="flex-1"
              >
                {isSubmitting ? 'Updating...' : 'Update Status'}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      {/* Remove Confirmation Modal */}
      <Dialog open={modalType === 'remove'} onOpenChange={closeModal}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Remove from Waitlist</DialogTitle>
            <DialogDescription>
              Are you sure you want to permanently remove {selectedEntry?.player.full_name} from the waitlist?
              This action cannot be undone.
            </DialogDescription>
          </DialogHeader>

          <div className="bg-red-50 border border-red-200 rounded-lg p-3 my-4">
            <p className="text-sm text-red-800">
              ⚠️ This will permanently remove the player from the waitlist. They will need to be manually re-added if needed.
            </p>
          </div>

          <div className="flex space-x-3">
            <Button
              variant="outline"
              onClick={closeModal}
              disabled={isSubmitting}
              className="flex-1"
            >
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={handleRemoveFromWaitlist}
              disabled={isSubmitting}
              className="flex-1"
            >
              {isSubmitting ? 'Removing...' : 'Remove from Waitlist'}
            </Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  )
}

import { useEffect, useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import {
  Bell, Plus, Edit, Trash2, Send, Eye, Filter, Search,
  RefreshCw, ArrowLeft, AlertCircle, CheckCircle, Mail,
  MessageSquare, Smartphone, Monitor
} from 'lucide-react'
import { Button } from './ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from './ui/card'
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from './ui/dialog'
import { Input } from './ui/input'
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from './ui/select'
import { useApi } from '../hooks/useApi'

interface NotificationTemplate {
  id: string
  name: string
  type: 'email' | 'sms' | 'push' | 'in_app'
  subject?: string
  body: string
  placeholders: Record<string, string>
  is_active: boolean
  created_by?: string
  created_at: string
  updated_at: string
}

interface Player {
  id: number
  first_name: string
  last_name: string
  full_name: string
  email: string
}

interface User {
  id: number
  first_name: string
  last_name: string
  email: string
}

interface NotificationTemplateManagementProps {
  onBack: () => void
}

type ModalType = 'create' | 'edit' | 'delete' | 'send' | 'preview' | null

const typeConfig = {
  email: { label: 'Email', icon: Mail, color: 'text-blue-600', bg: 'bg-blue-100' },
  sms: { label: 'SMS', icon: MessageSquare, color: 'text-green-600', bg: 'bg-green-100' },
  push: { label: 'Push', icon: Smartphone, color: 'text-purple-600', bg: 'bg-purple-100' },
  in_app: { label: 'In-App', icon: Monitor, color: 'text-orange-600', bg: 'bg-orange-100' }
}

const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.05
    }
  }
}

const itemVariants = {
  hidden: { y: 20, opacity: 0 },
  visible: {
    y: 0,
    opacity: 1,
    transition: {
      duration: 0.3
    }
  }
}

export default function NotificationTemplateManagement({ onBack }: NotificationTemplateManagementProps) {
  const [templates, setTemplates] = useState<NotificationTemplate[]>([])
  const [players, setPlayers] = useState<Player[]>([])
  const [users, setUsers] = useState<User[]>([])
  const [filteredTemplates, setFilteredTemplates] = useState<NotificationTemplate[]>([])
  const [selectedType, setSelectedType] = useState<string>('all')
  const [searchTerm, setSearchTerm] = useState('')
  const [loading, setLoading] = useState(false)

  // Modal states
  const [modalType, setModalType] = useState<ModalType>(null)
  const [selectedTemplate, setSelectedTemplate] = useState<NotificationTemplate | null>(null)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [message, setMessage] = useState<{ type: 'success' | 'error'; text: string } | null>(null)

  // Form states
  const [formData, setFormData] = useState({
    name: '',
    type: 'email' as 'email' | 'sms' | 'push' | 'in_app',
    subject: '',
    body: '',
    placeholders: {} as Record<string, string>,
    is_active: true
  })

  // Send notification states
  const [sendData, setSendData] = useState({
    template_id: '',
    recipient_type: 'player' as 'player' | 'user' | 'email',
    recipient_id: '',
    placeholders: {} as Record<string, string>
  })
  const [previewContent, setPreviewContent] = useState<{ subject?: string; body: string } | null>(null)

  const { execute } = useApi()

  useEffect(() => {
    fetchTemplates()
    fetchPlayers()
    fetchUsers()
  }, [])

  useEffect(() => {
    filterTemplates()
  }, [templates, selectedType, searchTerm])

  const fetchTemplates = async () => {
    setLoading(true)
    try {
      const response = await execute('/api/admin/registration/notification-templates')
      if (response?.templates) {
        setTemplates(response.templates)
      }
    } catch (error) {
      console.error('Error fetching templates:', error)
      setMessage({ type: 'error', text: 'Failed to fetch notification templates' })
    } finally {
      setLoading(false)
    }
  }

  const fetchPlayers = async () => {
    try {
      const response = await execute('/api/players')
      if (response?.players) {
        setPlayers(response.players.map((p: any) => ({
          ...p,
          full_name: `${p.first_name} ${p.last_name}`
        })))
      }
    } catch (error) {
      console.error('Error fetching players:', error)
    }
  }

  const fetchUsers = async () => {
    try {
      const response = await execute('/api/users')
      if (response?.users) {
        setUsers(response.users.map((u: any) => ({
          ...u,
          full_name: `${u.first_name} ${u.last_name}`
        })))
      }
    } catch (error) {
      console.error('Error fetching users:', error)
    }
  }

  const filterTemplates = () => {
    let filtered = templates

    if (selectedType !== 'all') {
      filtered = filtered.filter(template => template.type === selectedType)
    }

    if (searchTerm) {
      const searchLower = searchTerm.toLowerCase()
      filtered = filtered.filter(template =>
        template.name.toLowerCase().includes(searchLower) ||
        template.body.toLowerCase().includes(searchLower) ||
        (template.subject && template.subject.toLowerCase().includes(searchLower))
      )
    }

    setFilteredTemplates(filtered)
  }

  const formatDate = (dateString: string): string => {
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  }

  const validateForm = (): boolean => {
    if (!formData.name.trim()) {
      setMessage({ type: 'error', text: 'Template name is required' })
      return false
    }

    if (!formData.body.trim()) {
      setMessage({ type: 'error', text: 'Template body is required' })
      return false
    }

    if (formData.type === 'email' && !formData.subject.trim()) {
      setMessage({ type: 'error', text: 'Subject is required for email templates' })
      return false
    }

    return true
  }

  const openModal = (type: ModalType, template?: NotificationTemplate) => {
    setModalType(type)
    setSelectedTemplate(template || null)
    setMessage(null)

    if (type === 'create') {
      setFormData({
        name: '',
        type: 'email',
        subject: '',
        body: '',
        placeholders: {},
        is_active: true
      })
    } else if (type === 'edit' && template) {
      setFormData({
        name: template.name,
        type: template.type,
        subject: template.subject || '',
        body: template.body,
        placeholders: template.placeholders || {},
        is_active: template.is_active
      })
    } else if (type === 'send' && template) {
      setSendData({
        template_id: template.id,
        recipient_type: 'player',
        recipient_id: '',
        placeholders: {}
      })
      setPreviewContent(null)
    }
  }

  const closeModal = () => {
    setModalType(null)
    setSelectedTemplate(null)
    setMessage(null)
    setFormData({
      name: '',
      type: 'email',
      subject: '',
      body: '',
      placeholders: {},
      is_active: true
    })
    setSendData({
      template_id: '',
      recipient_type: 'player',
      recipient_id: '',
      placeholders: {}
    })
    setPreviewContent(null)
  }

  const handleCreateTemplate = async () => {
    if (!validateForm()) return

    setIsSubmitting(true)
    try {
      const response = await execute('/api/admin/registration/notification-templates', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: formData.name.trim(),
          type: formData.type,
          subject: formData.type === 'email' ? formData.subject.trim() : undefined,
          body: formData.body.trim(),
          placeholders: formData.placeholders
        })
      })

      if (response) {
        setMessage({ type: 'success', text: 'Template created successfully' })
        fetchTemplates()
        setTimeout(closeModal, 1500)
      }
    } catch (error: any) {
      setMessage({ type: 'error', text: error.message || 'Failed to create template' })
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleUpdateTemplate = async () => {
    if (!selectedTemplate || !validateForm()) return

    setIsSubmitting(true)
    try {
      const response = await execute(`/api/admin/registration/notification-templates/${selectedTemplate.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: formData.name.trim(),
          type: formData.type,
          subject: formData.type === 'email' ? formData.subject.trim() : undefined,
          body: formData.body.trim(),
          placeholders: formData.placeholders,
          is_active: formData.is_active
        })
      })

      if (response) {
        setMessage({ type: 'success', text: 'Template updated successfully' })
        fetchTemplates()
        setTimeout(closeModal, 1500)
      }
    } catch (error: any) {
      setMessage({ type: 'error', text: error.message || 'Failed to update template' })
    } finally {
      setIsSubmitting(false)
    }
  }

  const handleDeleteTemplate = async () => {
    if (!selectedTemplate) return

    setIsSubmitting(true)
    try {
      await execute(`/api/admin/registration/notification-templates/${selectedTemplate.id}`, {
        method: 'DELETE'
      })

      setMessage({ type: 'success', text: 'Template deleted successfully' })
      fetchTemplates()
      setTimeout(closeModal, 1500)
    } catch (error: any) {
      setMessage({ type: 'error', text: error.message || 'Failed to delete template' })
    } finally {
      setIsSubmitting(false)
    }
  }

  const generatePreview = () => {
    if (!selectedTemplate) return

    const substituteTemplate = (text: string): string => {
      let result = text

      // Built-in placeholders
      const builtInPlaceholders = {
        '{recipient_name}': sendData.recipient_type === 'email' ? 'Recipient' : getRecipientName(),
        '{recipient_email}': sendData.recipient_type === 'email' ? sendData.recipient_id : getRecipientEmail(),
        '{current_date}': new Date().toLocaleDateString(),
        '{current_time}': new Date().toLocaleTimeString()
      }

      // Apply built-in placeholders
      Object.entries(builtInPlaceholders).forEach(([placeholder, value]) => {
        result = result.replace(new RegExp(placeholder.replace(/[{}]/g, '\\$&'), 'g'), value || '')
      })

      // Apply custom placeholders
      Object.entries(sendData.placeholders).forEach(([key, value]) => {
        const placeholder = `{${key}}`
        result = result.replace(new RegExp(placeholder.replace(/[{}]/g, '\\$&'), 'g'), value || '')
      })

      return result
    }

    const processedSubject = selectedTemplate.subject ? substituteTemplate(selectedTemplate.subject) : undefined
    const processedBody = substituteTemplate(selectedTemplate.body)

    setPreviewContent({
      subject: processedSubject,
      body: processedBody
    })
  }

  const getRecipientName = (): string => {
    if (sendData.recipient_type === 'player') {
      const player = players.find(p => p.id.toString() === sendData.recipient_id)
      return player ? player.full_name : 'Player'
    } else if (sendData.recipient_type === 'user') {
      const user = users.find(u => u.id.toString() === sendData.recipient_id)
      return user ? user.full_name : 'User'
    }
    return 'Recipient'
  }

  const getRecipientEmail = (): string => {
    if (sendData.recipient_type === 'player') {
      const player = players.find(p => p.id.toString() === sendData.recipient_id)
      return player ? player.email : ''
    } else if (sendData.recipient_type === 'user') {
      const user = users.find(u => u.id.toString() === sendData.recipient_id)
      return user ? user.email : ''
    }
    return sendData.recipient_id
  }

  const handleSendNotification = async () => {
    if (!sendData.recipient_id) {
      setMessage({ type: 'error', text: 'Please select a recipient' })
      return
    }

    setIsSubmitting(true)
    try {
      const response = await execute('/api/admin/registration/send-notification', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(sendData)
      })

      if (response) {
        setMessage({ type: 'success', text: 'Notification sent successfully' })
        setTimeout(closeModal, 1500)
      }
    } catch (error: any) {
      setMessage({ type: 'error', text: error.message || 'Failed to send notification' })
    } finally {
      setIsSubmitting(false)
    }
  }

  const clearMessage = () => {
    setMessage(null)
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center space-x-4">
          <Button variant="outline" onClick={onBack} className="flex items-center space-x-2">
            <ArrowLeft className="h-4 w-4" />
            <span>Back to Dashboard</span>
          </Button>
          <div>
            <h2 className="text-2xl font-bold text-gray-900">Notification Templates</h2>
            <p className="text-gray-600">Create and manage notification templates</p>
          </div>
        </div>
        <div className="flex items-center space-x-2">
          <Button
            variant="outline"
            onClick={fetchTemplates}
            disabled={loading}
            className="flex items-center space-x-2"
          >
            <RefreshCw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
            <span>Refresh</span>
          </Button>
          <Button onClick={() => openModal('create')} className="flex items-center space-x-2">
            <Plus className="h-4 w-4" />
            <span>Create Template</span>
          </Button>
        </div>
      </div>

      {/* Message Display */}
      <AnimatePresence>
        {message && (
          <motion.div
            initial={{ opacity: 0, y: -10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className={`p-4 rounded-lg border ${
              message.type === 'success'
                ? 'bg-green-50 border-green-200 text-green-800'
                : 'bg-red-50 border-red-200 text-red-800'
            }`}
          >
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-2">
                {message.type === 'success' ? (
                  <CheckCircle className="h-5 w-5" />
                ) : (
                  <AlertCircle className="h-5 w-5" />
                )}
                <span>{message.text}</span>
              </div>
              <Button variant="ghost" size="sm" onClick={clearMessage}>
                ×
              </Button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Filters */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center space-x-2">
            <Filter className="h-5 w-5" />
            <span>Filters</span>
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Type</label>
              <Select value={selectedType} onValueChange={setSelectedType}>
                <SelectTrigger>
                  <SelectValue placeholder="Select type" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">All Types</SelectItem>
                  <SelectItem value="email">Email</SelectItem>
                  <SelectItem value="sms">SMS</SelectItem>
                  <SelectItem value="push">Push</SelectItem>
                  <SelectItem value="in_app">In-App</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="md:col-span-2">
              <label className="block text-sm font-medium text-gray-700 mb-1">Search</label>
              <div className="relative">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 h-4 w-4" />
                <Input
                  placeholder="Search templates by name, subject, or content"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10"
                />
              </div>
            </div>
          </div>
        </CardContent>
      </Card>

      {/* Templates List */}
      {loading ? (
        <div className="flex items-center justify-center py-12">
          <RefreshCw className="h-8 w-8 animate-spin text-gray-400" />
          <span className="ml-3 text-gray-500">Loading templates...</span>
        </div>
      ) : filteredTemplates.length === 0 ? (
        <Card>
          <CardContent className="flex items-center justify-center py-12">
            <div className="text-center">
              <Bell className="h-12 w-12 text-gray-400 mx-auto mb-4" />
              <h3 className="text-lg font-medium text-gray-900 mb-2">
                {searchTerm ? 'No templates match your search' : 'No notification templates'}
              </h3>
              <p className="text-gray-500 mb-4">
                {searchTerm ? 'Try adjusting your search criteria.' : 'Create your first notification template to get started.'}
              </p>
              {!searchTerm && (
                <Button onClick={() => openModal('create')}>
                  <Plus className="h-4 w-4 mr-2" />
                  Create Template
                </Button>
              )}
            </div>
          </CardContent>
        </Card>
      ) : (
        <motion.div
          variants={containerVariants}
          initial="hidden"
          animate="visible"
          className="space-y-4"
        >
          {filteredTemplates.map((template) => {
            const typeInfo = typeConfig[template.type]
            const TypeIcon = typeInfo.icon

            return (
              <motion.div key={template.id} variants={itemVariants}>
                <Card className="hover:shadow-md transition-shadow">
                  <CardContent className="p-6">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center space-x-4">
                        <div className={`p-2 rounded-lg ${typeInfo.bg}`}>
                          <TypeIcon className={`h-5 w-5 ${typeInfo.color}`} />
                        </div>
                        <div>
                          <h3 className="text-lg font-medium text-gray-900">{template.name}</h3>
                          <div className="flex items-center space-x-4 text-sm text-gray-500">
                            <span>{typeInfo.label}</span>
                            {template.subject && <span>• {template.subject}</span>}
                            <span>• Created {formatDate(template.created_at)}</span>
                          </div>
                          <div className="flex items-center space-x-2 mt-1">
                            <div className={`px-2 py-1 rounded-full text-xs font-medium ${
                              template.is_active
                                ? 'bg-green-100 text-green-800'
                                : 'bg-gray-100 text-gray-800'
                            }`}>
                              {template.is_active ? 'Active' : 'Inactive'}
                            </div>
                          </div>
                        </div>
                      </div>

                      <div className="flex items-center space-x-2">
                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => openModal('send', template)}
                          className="flex items-center space-x-1"
                        >
                          <Send className="h-4 w-4" />
                          <span>Send</span>
                        </Button>

                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => openModal('edit', template)}
                          className="flex items-center space-x-1"
                        >
                          <Edit className="h-4 w-4" />
                          <span>Edit</span>
                        </Button>

                        <Button
                          size="sm"
                          variant="outline"
                          onClick={() => openModal('delete', template)}
                          className="flex items-center space-x-1 text-red-600 hover:text-red-700"
                        >
                          <Trash2 className="h-4 w-4" />
                          <span>Delete</span>
                        </Button>
                      </div>
                    </div>

                    <div className="mt-4 p-3 bg-gray-50 rounded-lg">
                      <p className="text-sm text-gray-700 line-clamp-3">
                        {template.body}
                      </p>
                    </div>
                  </CardContent>
                </Card>
              </motion.div>
            )
          })}
        </motion.div>
      )}

      {/* Create/Edit Template Modal */}
      <Dialog open={modalType === 'create' || modalType === 'edit'} onOpenChange={closeModal}>
        <DialogContent className="sm:max-w-2xl">
          <DialogHeader>
            <DialogTitle>
              {modalType === 'create' ? 'Create' : 'Edit'} Notification Template
            </DialogTitle>
            <DialogDescription>
              {modalType === 'create'
                ? 'Create a new notification template for registration communications.'
                : 'Update the notification template details.'
              }
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Template Name
                </label>
                <Input
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  placeholder="Enter template name"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Type
                </label>
                <Select
                  value={formData.type}
                  onValueChange={(value: 'email' | 'sms' | 'push' | 'in_app') =>
                    setFormData({ ...formData, type: value, subject: value === 'email' ? formData.subject : '' })
                  }
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="email">Email</SelectItem>
                    <SelectItem value="sms">SMS</SelectItem>
                    <SelectItem value="push">Push</SelectItem>
                    <SelectItem value="in_app">In-App</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            {formData.type === 'email' && (
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Subject
                </label>
                <Input
                  value={formData.subject}
                  onChange={(e) => setFormData({ ...formData, subject: e.target.value })}
                  placeholder="Enter email subject"
                />
              </div>
            )}

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Message Body
              </label>
              <textarea
                value={formData.body}
                onChange={(e) => setFormData({ ...formData, body: e.target.value })}
                placeholder="Enter message content. Use {placeholders} for dynamic content."
                rows={6}
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              />
              <p className="text-sm text-gray-500 mt-1">
                Available placeholders: {'{recipient_name}'}, {'{recipient_email}'}, {'{current_date}'}, {'{current_time}'}
              </p>
            </div>

            <div className="flex items-center space-x-2">
              <input
                type="checkbox"
                id="is_active"
                checked={formData.is_active}
                onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })}
                className="rounded border-gray-300"
              />
              <label htmlFor="is_active" className="text-sm font-medium text-gray-700">
                Template is active
              </label>
            </div>

            <div className="flex space-x-3 pt-4">
              <Button
                variant="outline"
                onClick={closeModal}
                disabled={isSubmitting}
                className="flex-1"
              >
                Cancel
              </Button>
              <Button
                onClick={modalType === 'create' ? handleCreateTemplate : handleUpdateTemplate}
                disabled={isSubmitting}
                className="flex-1"
              >
                {isSubmitting ? 'Saving...' : modalType === 'create' ? 'Create Template' : 'Update Template'}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation Modal */}
      <Dialog open={modalType === 'delete'} onOpenChange={closeModal}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>Delete Template</DialogTitle>
            <DialogDescription>
              Are you sure you want to delete "{selectedTemplate?.name}"? This action cannot be undone.
            </DialogDescription>
          </DialogHeader>

          <div className="bg-red-50 border border-red-200 rounded-lg p-3 my-4">
            <p className="text-sm text-red-800">
              ⚠️ This will permanently delete the notification template. Any references to this template will be broken.
            </p>
          </div>

          <div className="flex space-x-3">
            <Button
              variant="outline"
              onClick={closeModal}
              disabled={isSubmitting}
              className="flex-1"
            >
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={handleDeleteTemplate}
              disabled={isSubmitting}
              className="flex-1"
            >
              {isSubmitting ? 'Deleting...' : 'Delete Template'}
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      {/* Send Notification Modal */}
      <Dialog open={modalType === 'send'} onOpenChange={closeModal}>
        <DialogContent className="sm:max-w-2xl">
          <DialogHeader>
            <DialogTitle>Send Notification</DialogTitle>
            <DialogDescription>
              Send "{selectedTemplate?.name}" to a specific recipient.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Recipient Type
                </label>
                <Select
                  value={sendData.recipient_type}
                  onValueChange={(value: 'player' | 'user' | 'email') =>
                    setSendData({ ...sendData, recipient_type: value, recipient_id: '' })
                  }
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="player">Player</SelectItem>
                    <SelectItem value="user">User</SelectItem>
                    <SelectItem value="email">Email Address</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Recipient
                </label>
                {sendData.recipient_type === 'email' ? (
                  <Input
                    value={sendData.recipient_id}
                    onChange={(e) => setSendData({ ...sendData, recipient_id: e.target.value })}
                    placeholder="Enter email address"
                    type="email"
                  />
                ) : (
                  <Select
                    value={sendData.recipient_id}
                    onValueChange={(value) => setSendData({ ...sendData, recipient_id: value })}
                  >
                    <SelectTrigger>
                      <SelectValue placeholder={`Select ${sendData.recipient_type}`} />
                    </SelectTrigger>
                    <SelectContent>
                      {sendData.recipient_type === 'player'
                        ? players.map((player) => (
                            <SelectItem key={player.id} value={player.id.toString()}>
                              {player.full_name} ({player.email})
                            </SelectItem>
                          ))
                        : users.map((user) => (
                            <SelectItem key={user.id} value={user.id.toString()}>
                              {user.full_name} ({user.email})
                            </SelectItem>
                          ))
                      }
                    </SelectContent>
                  </Select>
                )}
              </div>
            </div>

            {selectedTemplate && Object.keys(selectedTemplate.placeholders || {}).length > 0 && (
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Custom Placeholders
                </label>
                <div className="space-y-2">
                  {Object.entries(selectedTemplate.placeholders || {}).map(([key, description]) => (
                    <div key={key} className="grid grid-cols-3 gap-2 items-center">
                      <span className="text-sm text-gray-600">{key}:</span>
                      <div className="col-span-2">
                        <Input
                          value={sendData.placeholders[key] || ''}
                          onChange={(e) => setSendData({
                            ...sendData,
                            placeholders: { ...sendData.placeholders, [key]: e.target.value }
                          })}
                          placeholder={description}
                        />
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            <div className="flex space-x-3">
              <Button
                variant="outline"
                onClick={generatePreview}
                disabled={!sendData.recipient_id}
                className="flex items-center space-x-2"
              >
                <Eye className="h-4 w-4" />
                <span>Preview</span>
              </Button>
            </div>

            {previewContent && (
              <div className="border rounded-lg p-4 bg-gray-50">
                <h4 className="font-medium text-gray-900 mb-2">Preview</h4>
                {previewContent.subject && (
                  <div className="mb-2">
                    <strong className="text-sm text-gray-600">Subject:</strong>
                    <p className="text-sm">{previewContent.subject}</p>
                  </div>
                )}
                <div>
                  <strong className="text-sm text-gray-600">Body:</strong>
                  <p className="text-sm whitespace-pre-wrap">{previewContent.body}</p>
                </div>
              </div>
            )}

            <div className="flex space-x-3 pt-4">
              <Button
                variant="outline"
                onClick={closeModal}
                disabled={isSubmitting}
                className="flex-1"
              >
                Cancel
              </Button>
              <Button
                onClick={handleSendNotification}
                disabled={isSubmitting || !sendData.recipient_id}
                className="flex-1"
              >
                {isSubmitting ? 'Sending...' : 'Send Notification'}
              </Button>
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  )
}

