import React, { useState, useEffect, useCallback } from 'react'
import { motion } from 'framer-motion'
import {
  ChevronLeft,
  ChevronRight,
  Plus,
  Calendar,
  Clock,
  MapPin,
  Users,
  Edit3,
  Trash2,
  Eye,
  AlertTriangle
} from 'lucide-react'
import { Button } from './ui/button'
import { Card, CardContent, CardHeader, CardTitle } from './ui/card'
import { Alert, AlertDescription } from './ui/alert'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle
} from './ui/dialog'
import { useApi } from '../hooks/useApi'

interface Event {
  id: string
  title: string
  description?: string
  event_type: 'game' | 'practice' | 'tournament'
  start_time: string
  end_time: string
  venue_id?: string
  venues?: {
    id: string
    name: string
    address?: string
    city?: string
    state?: string
  }
  created_by_user_id?: number
  is_recurring: boolean
  recurrence_rule?: string
  status: 'scheduled' | 'completed' | 'cancelled'
  created_at: string
  updated_at: string
}

interface EventsResponse {
  events: Event[]
  pagination: {
    page: number
    limit: number
    total: number
    pages: number
  }
}

type ViewMode = 'month' | 'week' | 'day'

interface EventCalendarProps {
  className?: string
  onCreateEvent?: (date?: Date) => void
  onEditEvent?: (eventId: string) => void
}

const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.1
    }
  }
}

const itemVariants = {
  hidden: { y: 20, opacity: 0 },
  visible: {
    y: 0,
    opacity: 1,
    transition: {
      duration: 0.3
    }
  }
}

export default function EventCalendar({
  className = '',
  onCreateEvent,
  onEditEvent
}: EventCalendarProps) {
  const [currentDate, setCurrentDate] = useState(new Date())
  const [selectedDate, setSelectedDate] = useState<Date | null>(null)
  const [viewMode, setViewMode] = useState<ViewMode>('month')
  const [selectedEvent, setSelectedEvent] = useState<Event | null>(null)
  const [showEventDetails, setShowEventDetails] = useState(false)
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false)
  const [eventToDelete, setEventToDelete] = useState<string | null>(null)

  const { data: eventsData, loading, error, execute: fetchEvents } = useApi<EventsResponse>()
  const { execute: deleteEvent, loading: deleting } = useApi()

  // Calculate date range for current view
  const getDateRange = useCallback(() => {
    const start = new Date(currentDate)
    const end = new Date(currentDate)

    switch (viewMode) {
      case 'month':
        start.setDate(1)
        end.setMonth(end.getMonth() + 1, 0)
        break
      case 'week':
        const dayOfWeek = start.getDay()
        start.setDate(start.getDate() - dayOfWeek)
        end.setDate(start.getDate() + 6)
        break
      case 'day':
        // Same day
        break
    }

    return {
      start: start.toISOString().split('T')[0],
      end: end.toISOString().split('T')[0]
    }
  }, [currentDate, viewMode])

  // Fetch events for current date range
  const loadEvents = useCallback(async () => {
    try {
      const { start, end } = getDateRange()
      const params = new URLSearchParams({
        start_date_after: start,
        end_date_before: end + 'T23:59:59',
        limit: '100'
      })

      await fetchEvents(`/api/events?${params}`)
    } catch (err) {
      console.error('Failed to load events:', err)
    }
  }, [fetchEvents, getDateRange])

  // Load events when date range changes
  useEffect(() => {
    loadEvents()
  }, [loadEvents])

  // Handle event deletion
  const handleDeleteEvent = async () => {
    if (!eventToDelete) return

    try {
      await deleteEvent(`/api/events/${eventToDelete}`, { method: 'DELETE' })
      setShowDeleteConfirm(false)
      setEventToDelete(null)
      setShowEventDetails(false)
      setSelectedEvent(null)
      await loadEvents() // Refresh events
    } catch (err) {
      console.error('Failed to delete event:', err)
    }
  }

  // Get events for a specific date
  const getEventsForDate = (date: Date): Event[] => {
    if (!eventsData?.events) return []

    const dateStr = date.toISOString().split('T')[0]
    return eventsData.events.filter(event => {
      const eventDate = new Date(event.start_time).toISOString().split('T')[0]
      return eventDate === dateStr
    })
  }

  // Get events for a specific hour
  const getEventsForHour = (date: Date, hour: number): Event[] => {
    const dayEvents = getEventsForDate(date)
    return dayEvents.filter(event => {
      const eventHour = new Date(event.start_time).getHours()
      return eventHour === hour
    })
  }

  // Event type color mapping
  const getEventTypeColor = (type: string) => {
    switch (type) {
      case 'game':
        return 'bg-blue-100 text-blue-800 border-blue-200 hover:bg-blue-200'
      case 'practice':
        return 'bg-green-100 text-green-800 border-green-200 hover:bg-green-200'
      case 'tournament':
        return 'bg-purple-100 text-purple-800 border-purple-200 hover:bg-purple-200'
      default:
        return 'bg-gray-100 text-gray-800 border-gray-200 hover:bg-gray-200'
    }
  }

  // Navigation handlers
  const handlePrevious = () => {
    const newDate = new Date(currentDate)
    switch (viewMode) {
      case 'month':
        newDate.setMonth(newDate.getMonth() - 1)
        break
      case 'week':
        newDate.setDate(newDate.getDate() - 7)
        break
      case 'day':
        newDate.setDate(newDate.getDate() - 1)
        break
    }
    setCurrentDate(newDate)
  }

  const handleNext = () => {
    const newDate = new Date(currentDate)
    switch (viewMode) {
      case 'month':
        newDate.setMonth(newDate.getMonth() + 1)
        break
      case 'week':
        newDate.setDate(newDate.getDate() + 7)
        break
      case 'day':
        newDate.setDate(newDate.getDate() + 1)
        break
    }
    setCurrentDate(newDate)
  }

  // Calendar helpers
  const getDaysInMonth = (date: Date) => {
    const year = date.getFullYear()
    const month = date.getMonth()
    const firstDay = new Date(year, month, 1).getDay()
    const daysInMonth = new Date(year, month + 1, 0).getDate()

    const days = []
    for (let i = 0; i < firstDay; i++) {
      days.push(null)
    }
    for (let i = 1; i <= daysInMonth; i++) {
      days.push(i)
    }
    return days
  }

  const getWeekDays = (date: Date) => {
    const startOfWeek = new Date(date)
    const day = startOfWeek.getDay()
    startOfWeek.setDate(startOfWeek.getDate() - day)

    const week = []
    for (let i = 0; i < 7; i++) {
      const weekDay = new Date(startOfWeek)
      weekDay.setDate(startOfWeek.getDate() + i)
      week.push(weekDay)
    }
    return week
  }

  // Date comparison helpers
  const isToday = (date: Date | number | null) => {
    const today = new Date()
    if (typeof date === 'number') {
      return (
        currentDate.getFullYear() === today.getFullYear() &&
        currentDate.getMonth() === today.getMonth() &&
        date === today.getDate()
      )
    } else if (date instanceof Date) {
      return (
        date.getFullYear() === today.getFullYear() &&
        date.getMonth() === today.getMonth() &&
        date.getDate() === today.getDate()
      )
    }
    return false
  }

  const isSelected = (date: Date | number | null) => {
    if (!selectedDate) return false

    if (typeof date === 'number') {
      return (
        currentDate.getFullYear() === selectedDate.getFullYear() &&
        currentDate.getMonth() === selectedDate.getMonth() &&
        date === selectedDate.getDate()
      )
    } else if (date instanceof Date) {
      return (
        date.getFullYear() === selectedDate.getFullYear() &&
        date.getMonth() === selectedDate.getMonth() &&
        date.getDate() === selectedDate.getDate()
      )
    }
    return false
  }

  const handleDateClick = (day: number) => {
    const newDate = new Date(currentDate.getFullYear(), currentDate.getMonth(), day)
    setSelectedDate(newDate)
  }

  const handleEmptySlotClick = (date?: Date) => {
    if (onCreateEvent) {
      onCreateEvent(date)
    }
  }

  const handleEventClick = (event: Event) => {
    setSelectedEvent(event)
    setShowEventDetails(true)
  }

  const handleEditClick = (eventId: string) => {
    if (onEditEvent) {
      onEditEvent(eventId)
    }
    setShowEventDetails(false)
  }

  const handleDeleteClick = (eventId: string) => {
    setEventToDelete(eventId)
    setShowDeleteConfirm(true)
  }

  const formatTime = (dateString: string) => {
    const date = new Date(dateString)
    return date.toLocaleTimeString('en-US', {
      hour: 'numeric',
      minute: '2-digit',
      hour12: true
    })
  }

  const formatDuration = (startTime: string, endTime: string) => {
    return `${formatTime(startTime)} - ${formatTime(endTime)}`
  }

  // Constants
  const monthNames = [
    'January', 'February', 'March', 'April', 'May', 'June',
    'July', 'August', 'September', 'October', 'November', 'December'
  ]
  const weekDayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
  const days = getDaysInMonth(currentDate)
  const weekDays = getWeekDays(currentDate)

  return (
    <motion.div
      variants={containerVariants}
      initial="hidden"
      animate="visible"
      className={`space-y-6 ${className}`}
    >
      {/* Error Display */}
      {error && (
        <Alert className="border-red-200 bg-red-50">
          <AlertTriangle className="h-4 w-4 text-red-600" />
          <AlertDescription className="text-red-800">
            {error}
          </AlertDescription>
        </Alert>
      )}

      {/* Calendar Header */}
      <motion.div variants={itemVariants}>
        <Card className="border-zinc-200 shadow-lg bg-white">
          <CardHeader className="pb-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-4">
                <CardTitle className="text-2xl font-bold text-gray-900">
                  {viewMode === 'month' && `${monthNames[currentDate.getMonth()]} ${currentDate.getFullYear()}`}
                  {viewMode === 'week' && `Week of ${weekDays[0]?.toLocaleDateString()}`}
                  {viewMode === 'day' && currentDate.toLocaleDateString('en-US', {
                    weekday: 'long',
                    year: 'numeric',
                    month: 'long',
                    day: 'numeric'
                  })}
                </CardTitle>
                <div className="flex items-center space-x-2">
                  <Button
                    variant="outline"
                    size="icon"
                    onClick={handlePrevious}
                    className="h-8 w-8"
                    disabled={loading}
                  >
                    <ChevronLeft className="h-4 w-4" />
                  </Button>
                  <Button
                    variant="outline"
                    size="icon"
                    onClick={handleNext}
                    className="h-8 w-8"
                    disabled={loading}
                  >
                    <ChevronRight className="h-4 w-4" />
                  </Button>
                </div>
              </div>
              <div className="flex items-center space-x-2">
                <Button
                  variant={viewMode === 'month' ? 'default' : 'outline'}
                  size="sm"
                  onClick={() => setViewMode('month')}
                  className={viewMode === 'month' ? 'bg-blue-600 hover:bg-blue-700' : ''}
                >
                  Month
                </Button>
                <Button
                  variant={viewMode === 'week' ? 'default' : 'outline'}
                  size="sm"
                  onClick={() => setViewMode('week')}
                  className={viewMode === 'week' ? 'bg-blue-600 hover:bg-blue-700' : ''}
                >
                  Week
                </Button>
                <Button
                  variant={viewMode === 'day' ? 'default' : 'outline'}
                  size="sm"
                  onClick={() => setViewMode('day')}
                  className={viewMode === 'day' ? 'bg-blue-600 hover:bg-blue-700' : ''}
                >
                  Day
                </Button>
                <div className="h-4 w-px bg-zinc-300 mx-2" />
                <Button
                  onClick={() => handleEmptySlotClick()}
                  className="bg-green-600 hover:bg-green-700 text-white"
                  disabled={loading}
                >
                  <Plus className="h-4 w-4 mr-2" />
                  New Event
                </Button>
              </div>
            </div>
          </CardHeader>
          <CardContent>
            {loading && (
              <div className="flex items-center justify-center py-8">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
                <span className="ml-2 text-gray-600">Loading events...</span>
              </div>
            )}

            {!loading && (
              <>
                {/* Month View */}
                {viewMode === 'month' && (
                  <div className="grid grid-cols-7 gap-px bg-zinc-200 rounded-lg overflow-hidden">
                    {/* Week Day Headers */}
                    {weekDayNames.map(day => (
                      <div
                        key={day}
                        className="bg-zinc-50 p-3 text-center text-sm font-semibold text-zinc-700"
                      >
                        {day}
                      </div>
                    ))}

                    {/* Calendar Days */}
                    {days.map((day, index) => {
                      const dayEvents = day ? getEventsForDate(
                        new Date(currentDate.getFullYear(), currentDate.getMonth(), day)
                      ) : []

                      return (
                        <div
                          key={index}
                          className={`
                            bg-white min-h-[100px] p-2 cursor-pointer transition-all
                            ${!day ? 'bg-zinc-50' : ''}
                            ${isToday(day) ? 'bg-blue-50 ring-2 ring-blue-400' : ''}
                            ${isSelected(day) ? 'bg-green-50 ring-2 ring-green-400' : ''}
                            ${day && !isToday(day) && !isSelected(day) ? 'hover:bg-zinc-50' : ''}
                          `}
                          onClick={() => {
                            if (day) {
                              handleDateClick(day)
                              if (dayEvents.length === 0) {
                                handleEmptySlotClick(new Date(currentDate.getFullYear(), currentDate.getMonth(), day))
                              }
                            }
                          }}
                        >
                          {day && (
                            <>
                              <div className={`
                                text-sm font-medium mb-1
                                ${isToday(day) ? 'text-blue-600' : 'text-zinc-700'}
                              `}>
                                {day}
                              </div>
                              <div className="space-y-1">
                                {dayEvents.slice(0, 2).map(event => (
                                  <div
                                    key={event.id}
                                    onClick={(e) => {
                                      e.stopPropagation()
                                      handleEventClick(event)
                                    }}
                                    className={`
                                      text-xs p-1 rounded border cursor-pointer
                                      transition-all hover:shadow-md
                                      ${getEventTypeColor(event.event_type)}
                                    `}
                                  >
                                    <div className="font-medium truncate">{event.title}</div>
                                    <div className="truncate opacity-75">{formatTime(event.start_time)}</div>
                                  </div>
                                ))}
                                {dayEvents.length > 2 && (
                                  <div className="text-xs text-zinc-500 text-center">
                                    +{dayEvents.length - 2} more
                                  </div>
                                )}
                              </div>
                            </>
                          )}
                        </div>
                      )
                    })}
                  </div>
                )}

                {/* Week View */}
                {viewMode === 'week' && (
                  <div className="grid grid-cols-8 gap-px bg-zinc-200 rounded-lg overflow-hidden">
                    {/* Time column header */}
                    <div className="bg-zinc-50 p-3 text-center text-sm font-semibold text-zinc-700">
                      Time
                    </div>
                    {/* Week day headers */}
                    {weekDays.map(date => (
                      <div
                        key={date.toISOString()}
                        className={`
                          bg-zinc-50 p-3 text-center text-sm font-semibold cursor-pointer transition-colors
                          ${isToday(date) ? 'bg-blue-100 text-blue-600' : 'text-zinc-700'}
                          ${isSelected(date) ? 'bg-green-100 text-green-600' : ''}
                        `}
                        onClick={() => setSelectedDate(date)}
                      >
                        <div>{weekDayNames[date.getDay()]}</div>
                        <div className="text-lg font-bold">{date.getDate()}</div>
                      </div>
                    ))}

                    {/* Time slots */}
                    {Array.from({ length: 18 }, (_, i) => i + 6).map(hour => (
                      <React.Fragment key={hour}>
                        <div className="bg-white p-2 text-xs text-zinc-500 border-r border-zinc-200">
                          {hour}:00
                        </div>
                        {weekDays.map(date => {
                          const hourEvents = getEventsForHour(date, hour)
                          return (
                            <div
                              key={`${date.toISOString()}-${hour}`}
                              className={`
                                bg-white min-h-[40px] p-1 cursor-pointer transition-colors border-b border-zinc-100
                                ${isToday(date) ? 'bg-blue-50/30' : ''}
                                hover:bg-zinc-50
                              `}
                              onClick={() => {
                                setSelectedDate(date)
                                if (hourEvents.length === 0) {
                                  const clickDate = new Date(date)
                                  clickDate.setHours(hour, 0, 0, 0)
                                  handleEmptySlotClick(clickDate)
                                }
                              }}
                            >
                              {hourEvents.map(event => (
                                <div
                                  key={event.id}
                                  onClick={(e) => {
                                    e.stopPropagation()
                                    handleEventClick(event)
                                  }}
                                  className={`
                                    text-xs p-1 rounded border cursor-pointer mb-1
                                    transition-all hover:shadow-md
                                    ${getEventTypeColor(event.event_type)}
                                  `}
                                >
                                  <div className="font-medium truncate">{event.title}</div>
                                </div>
                              ))}
                            </div>
                          )
                        })}
                      </React.Fragment>
                    ))}
                  </div>
                )}

                {/* Day View */}
                {viewMode === 'day' && (
                  <div className="space-y-2">
                    <div className="grid grid-cols-2 gap-px bg-zinc-200 rounded-lg overflow-hidden">
                      <div className="bg-zinc-50 p-2 text-sm font-semibold text-zinc-700">Time</div>
                      <div className="bg-zinc-50 p-2 text-sm font-semibold text-zinc-700">Events</div>

                      {Array.from({ length: 18 }, (_, i) => i + 6).map(hour => {
                        const hourEvents = getEventsForHour(currentDate, hour)

                        return (
                          <React.Fragment key={hour}>
                            <div className="bg-white p-3 text-sm text-zinc-600 border-r border-zinc-200">
                              {hour}:00
                            </div>
                            <div
                              className="bg-white min-h-[60px] p-2 cursor-pointer hover:bg-zinc-50 transition-colors"
                              onClick={() => {
                                if (hourEvents.length === 0) {
                                  const clickDate = new Date(currentDate)
                                  clickDate.setHours(hour, 0, 0, 0)
                                  handleEmptySlotClick(clickDate)
                                }
                              }}
                            >
                              {hourEvents.length > 0 ? (
                                <div className="space-y-2">
                                  {hourEvents.map(event => (
                                    <div
                                      key={event.id}
                                      onClick={(e) => {
                                        e.stopPropagation()
                                        handleEventClick(event)
                                      }}
                                      className={`
                                        p-2 rounded border cursor-pointer
                                        transition-all hover:shadow-md
                                        ${getEventTypeColor(event.event_type)}
                                      `}
                                    >
                                      <div className="font-medium">{event.title}</div>
                                      <div className="text-sm opacity-75">{formatDuration(event.start_time, event.end_time)}</div>
                                      {event.venues && (
                                        <div className="text-sm opacity-75">{event.venues.name}</div>
                                      )}
                                    </div>
                                  ))}
                                </div>
                              ) : (
                                <div className="text-center text-zinc-400 text-sm py-4">
                                  Click to add event
                                </div>
                              )}
                            </div>
                          </React.Fragment>
                        )
                      })}
                    </div>
                  </div>
                )}

                {/* Legend */}
                <div className="mt-4 flex items-center justify-between">
                  <div className="flex items-center space-x-4 text-sm">
                    <div className="flex items-center space-x-2">
                      <div className="w-3 h-3 rounded bg-blue-200 border border-blue-300" />
                      <span className="text-zinc-600">Game</span>
                    </div>
                    <div className="flex items-center space-x-2">
                      <div className="w-3 h-3 rounded bg-green-200 border border-green-300" />
                      <span className="text-zinc-600">Practice</span>
                    </div>
                    <div className="flex items-center space-x-2">
                      <div className="w-3 h-3 rounded bg-purple-200 border border-purple-300" />
                      <span className="text-zinc-600">Tournament</span>
                    </div>
                  </div>
                  <div className="text-sm text-zinc-500">
                    {eventsData?.events?.length || 0} events {
                      viewMode === 'month' ? 'this month' :
                      viewMode === 'week' ? 'this week' :
                      'today'
                    }
                  </div>
                </div>
              </>
            )}
          </CardContent>
        </Card>
      </motion.div>

      {/* Selected Date Events */}
      {selectedDate && !loading && (
        <motion.div variants={itemVariants}>
          <Card className="border-zinc-200 shadow-lg bg-white">
            <CardHeader>
              <CardTitle className="text-lg font-semibold text-gray-900 flex items-center">
                <Calendar className="h-5 w-5 mr-2 text-blue-500" />
                Events for {selectedDate.toLocaleDateString('en-US', {
                  weekday: 'long',
                  year: 'numeric',
                  month: 'long',
                  day: 'numeric'
                })}
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-3">
                {getEventsForDate(selectedDate).length > 0 ? (
                  getEventsForDate(selectedDate).map(event => (
                    <div
                      key={event.id}
                      className="p-4 border border-zinc-200 rounded-lg hover:shadow-md transition-all cursor-pointer"
                      onClick={() => handleEventClick(event)}
                    >
                      <div className="flex items-start justify-between">
                        <div className="flex-1">
                          <div className="flex items-center space-x-2 mb-2">
                            <h3 className="font-semibold text-gray-900">{event.title}</h3>
                            <span className={`text-xs px-2 py-1 rounded-full ${getEventTypeColor(event.event_type)}`}>
                              {event.event_type}
                            </span>
                          </div>
                          <div className="space-y-1 text-sm text-zinc-600">
                            <div className="flex items-center">
                              <Clock className="h-4 w-4 mr-2 text-zinc-400" />
                              {formatDuration(event.start_time, event.end_time)}
                            </div>
                            {event.venues && (
                              <div className="flex items-center">
                                <MapPin className="h-4 w-4 mr-2 text-zinc-400" />
                                {event.venues.name}
                                {event.venues.city && `, ${event.venues.city}`}
                              </div>
                            )}
                          </div>
                        </div>
                        <div className="flex space-x-2">
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={(e) => {
                              e.stopPropagation()
                              handleEventClick(event)
                            }}
                          >
                            <Eye className="h-4 w-4" />
                          </Button>
                          <Button
                            variant="outline"
                            size="sm"
                            onClick={(e) => {
                              e.stopPropagation()
                              handleEditClick(event.id)
                            }}
                          >
                            <Edit3 className="h-4 w-4" />
                          </Button>
                        </div>
                      </div>
                    </div>
                  ))
                ) : (
                  <div className="text-center py-8 text-zinc-500">
                    <Calendar className="h-12 w-12 mx-auto mb-3 text-zinc-300" />
                    <p>No events scheduled for this date</p>
                    <Button
                      variant="outline"
                      size="sm"
                      className="mt-3"
                      onClick={() => handleEmptySlotClick(selectedDate)}
                    >
                      <Plus className="h-4 w-4 mr-2" />
                      Add Event
                    </Button>
                  </div>
                )}
              </div>
            </CardContent>
          </Card>
        </motion.div>
      )}

      {/* Event Details Modal */}
      <Dialog open={showEventDetails} onOpenChange={setShowEventDetails}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle className="flex items-center">
              <Calendar className="h-5 w-5 mr-2 text-blue-500" />
              Event Details
            </DialogTitle>
          </DialogHeader>

          {selectedEvent && (
            <div className="space-y-4">
              <div className="flex items-center space-x-2">
                <h3 className="text-xl font-semibold">{selectedEvent.title}</h3>
                <span className={`text-sm px-3 py-1 rounded-full ${getEventTypeColor(selectedEvent.event_type)}`}>
                  {selectedEvent.event_type}
                </span>
                <span className={`text-sm px-3 py-1 rounded-full ${
                  selectedEvent.status === 'scheduled' ? 'bg-green-100 text-green-800' :
                  selectedEvent.status === 'completed' ? 'bg-blue-100 text-blue-800' :
                  'bg-red-100 text-red-800'
                }`}>
                  {selectedEvent.status}
                </span>
              </div>

              {selectedEvent.description && (
                <p className="text-gray-600">{selectedEvent.description}</p>
              )}

              <div className="grid grid-cols-2 gap-4 text-sm">
                <div className="flex items-center">
                  <Clock className="h-4 w-4 mr-2 text-zinc-400" />
                  <span>{formatDuration(selectedEvent.start_time, selectedEvent.end_time)}</span>
                </div>

                {selectedEvent.venues && (
                  <div className="flex items-center">
                    <MapPin className="h-4 w-4 mr-2 text-zinc-400" />
                    <span>
                      {selectedEvent.venues.name}
                      {selectedEvent.venues.address && (
                        <div className="text-xs text-gray-500 mt-1">
                          {selectedEvent.venues.address}
                          {selectedEvent.venues.city && `, ${selectedEvent.venues.city}`}
                          {selectedEvent.venues.state && `, ${selectedEvent.venues.state}`}
                        </div>
                      )}
                    </span>
                  </div>
                )}
              </div>

              {selectedEvent.is_recurring && selectedEvent.recurrence_rule && (
                <div className="bg-blue-50 p-3 rounded-lg">
                  <p className="text-sm text-blue-800">
                    <strong>Recurring Event:</strong> {selectedEvent.recurrence_rule}
                  </p>
                </div>
              )}
            </div>
          )}

          <DialogFooter className="space-x-2">
            <Button
              variant="outline"
              onClick={() => setShowEventDetails(false)}
            >
              Close
            </Button>
            {selectedEvent && (
              <>
                <Button
                  variant="outline"
                  onClick={() => handleEditClick(selectedEvent.id)}
                >
                  <Edit3 className="h-4 w-4 mr-2" />
                  Edit
                </Button>
                <Button
                  variant="destructive"
                  onClick={() => handleDeleteClick(selectedEvent.id)}
                >
                  <Trash2 className="h-4 w-4 mr-2" />
                  Delete
                </Button>
              </>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation Modal */}
      <Dialog open={showDeleteConfirm} onOpenChange={setShowDeleteConfirm}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle className="flex items-center">
              <AlertTriangle className="h-5 w-5 mr-2 text-red-500" />
              Confirm Deletion
            </DialogTitle>
            <DialogDescription>
              Are you sure you want to delete this event? This action cannot be undone.
            </DialogDescription>
          </DialogHeader>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setShowDeleteConfirm(false)}
              disabled={deleting}
            >
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={handleDeleteEvent}
              disabled={deleting}
            >
              {deleting ? (
                <>
                  <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
                  Deleting...
                </>
              ) : (
                <>
                  <Trash2 className="h-4 w-4 mr-2" />
                  Delete Event
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </motion.div>
  )
}

import React, { useState, useEffect } from 'react'
import { motion } from 'framer-motion'
import {
  Calendar,
  Clock,
  MapPin,
  Repeat,
  AlertTriangle,
  Search,
  Check,
  X,
  Settings,
  Users,
  Trophy
} from 'lucide-react'
import { Button } from './ui/button'
import { Input } from './ui/input'
import { Card, CardContent, CardHeader, CardTitle } from './ui/card'
import { Alert, AlertDescription } from './ui/alert'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle
} from './ui/dialog'
import { useApi } from '../hooks/useApi'

interface Venue {
  id: string
  name: string
  address?: string
  city?: string
  state?: string
  zip_code?: string
  capacity?: number
  description?: string
  is_active?: boolean
}

interface VenuesResponse {
  venues: Venue[]
  pagination: {
    page: number
    limit: number
    total: number
    pages: number
  }
}

interface Event {
  id: string
  title: string
  description?: string
  event_type: 'game' | 'practice' | 'tournament'
  start_time: string
  end_time: string
  venue_id?: string
  venues?: Venue
  created_by_user_id?: number
  is_recurring: boolean
  recurrence_rule?: string
  status: 'scheduled' | 'completed' | 'cancelled'
  created_at: string
  updated_at: string
}

interface EventFormData {
  name: string
  description: string
  event_type: 'game' | 'practice' | 'tournament'
  start_time: string
  end_time: string
  venue_id: string
  created_by_user_id?: number
  is_recurring: boolean
  recurrence_rule: string
}

interface EventFormComponentProps {
  mode: 'create' | 'edit'
  eventId?: string
  initialDate?: Date
  onSuccess?: (event: Event) => void
  onCancel?: () => void
  isModal?: boolean
}

const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.1
    }
  }
}

const itemVariants = {
  hidden: { y: 20, opacity: 0 },
  visible: {
    y: 0,
    opacity: 1,
    transition: {
      duration: 0.3
    }
  }
}

export default function EventFormComponent({
  mode = 'create',
  eventId,
  initialDate,
  onSuccess,
  onCancel,
  isModal = false
}: EventFormComponentProps) {
  const [formData, setFormData] = useState<EventFormData>({
    name: '',
    description: '',
    event_type: 'practice',
    start_time: '',
    end_time: '',
    venue_id: '',
    created_by_user_id: undefined,
    is_recurring: false,
    recurrence_rule: ''
  })

  const [formErrors, setFormErrors] = useState<Partial<Record<keyof EventFormData, string>>>({})
  const [venueSearch, setVenueSearch] = useState('')
  const [showVenueDropdown, setShowVenueDropdown] = useState(false)
  const [successMessage, setSuccessMessage] = useState('')

  // API hooks
  const { data: venuesData, loading: venuesLoading, execute: fetchVenues } = useApi<VenuesResponse>()
  const { data: eventData, loading: eventLoading, execute: fetchEvent } = useApi<Event>()
  const { loading: submitting, error: submitError, execute: submitEvent } = useApi<Event>()

  // Initialize form with initial date if provided
  useEffect(() => {
    if (initialDate && mode === 'create') {
      const startDateTime = new Date(initialDate)
      const endDateTime = new Date(initialDate)
      endDateTime.setHours(startDateTime.getHours() + 1)

      setFormData(prev => ({
        ...prev,
        start_time: startDateTime.toISOString().slice(0, 16),
        end_time: endDateTime.toISOString().slice(0, 16)
      }))
    }
  }, [initialDate, mode])

  // Fetch event data for edit mode
  useEffect(() => {
    if (mode === 'edit' && eventId) {
      fetchEvent(`/api/events/${eventId}`)
    }
  }, [mode, eventId, fetchEvent])

  // Populate form when event data is loaded
  useEffect(() => {
    if (eventData && mode === 'edit') {
      setFormData({
        name: eventData.title,
        description: eventData.description || '',
        event_type: eventData.event_type,
        start_time: new Date(eventData.start_time).toISOString().slice(0, 16),
        end_time: new Date(eventData.end_time).toISOString().slice(0, 16),
        venue_id: eventData.venue_id || '',
        created_by_user_id: eventData.created_by_user_id,
        is_recurring: eventData.is_recurring,
        recurrence_rule: eventData.recurrence_rule || ''
      })

      if (eventData.venues) {
        setVenueSearch(eventData.venues.name)
      }
    }
  }, [eventData, mode])

  // Fetch venues
  useEffect(() => {
    fetchVenues('/api/venues?limit=100')
  }, [fetchVenues])

  // Filter venues based on search
  const filteredVenues = venuesData?.venues?.filter(venue =>
    venue.name.toLowerCase().includes(venueSearch.toLowerCase()) ||
    venue.city?.toLowerCase().includes(venueSearch.toLowerCase()) ||
    venue.address?.toLowerCase().includes(venueSearch.toLowerCase())
  ) || []

  // Validation
  const validateForm = (): boolean => {
    const errors: Partial<Record<keyof EventFormData, string>> = {}

    // Required fields
    if (!formData.name.trim()) {
      errors.name = 'Event name is required'
    }
    if (!formData.event_type) {
      errors.event_type = 'Event type is required'
    }
    if (!formData.start_time) {
      errors.start_time = 'Start time is required'
    }
    if (!formData.end_time) {
      errors.end_time = 'End time is required'
    }

    // Time validation
    if (formData.start_time && formData.end_time) {
      const startDate = new Date(formData.start_time)
      const endDate = new Date(formData.end_time)

      if (isNaN(startDate.getTime()) || isNaN(endDate.getTime())) {
        errors.start_time = 'Invalid date format'
      } else {
        if (endDate <= startDate) {
          errors.end_time = 'End time must be after start time'
        }
        if (startDate < new Date() && mode === 'create') {
          errors.start_time = 'Start time cannot be in the past'
        }
      }
    }

    // Recurring event validation
    if (formData.is_recurring && !formData.recurrence_rule.trim()) {
      errors.recurrence_rule = 'Recurrence rule is required for recurring events'
    }

    setFormErrors(errors)
    return Object.keys(errors).length === 0
  }

  // Handle form submission
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!validateForm()) {
      return
    }

    try {
      const eventPayload = {
        name: formData.name.trim(),
        description: formData.description.trim(),
        event_type: formData.event_type,
        start_time: new Date(formData.start_time).toISOString(),
        end_time: new Date(formData.end_time).toISOString(),
        venue_id: formData.venue_id || undefined,
        created_by_user_id: formData.created_by_user_id,
        is_recurring: formData.is_recurring,
        recurrence_rule: formData.is_recurring ? formData.recurrence_rule : undefined
      }

      let result: Event
      if (mode === 'create') {
        result = await submitEvent('/api/events', {
          method: 'POST',
          body: eventPayload
        })
        setSuccessMessage('Event created successfully!')
      } else {
        result = await submitEvent(`/api/events/${eventId}`, {
          method: 'PUT',
          body: eventPayload
        })
        setSuccessMessage('Event updated successfully!')
      }

      if (onSuccess) {
        onSuccess(result)
      }

      // Reset form if creating
      if (mode === 'create') {
        setFormData({
          name: '',
          description: '',
          event_type: 'practice',
          start_time: '',
          end_time: '',
          venue_id: '',
          created_by_user_id: undefined,
          is_recurring: false,
          recurrence_rule: ''
        })
        setVenueSearch('')
      }

      // Clear success message after 3 seconds
      setTimeout(() => setSuccessMessage(''), 3000)

    } catch (error) {
      console.error('Form submission error:', error)
    }
  }

  // Handle venue selection
  const handleVenueSelect = (venue: Venue) => {
    setFormData(prev => ({ ...prev, venue_id: venue.id }))
    setVenueSearch(venue.name)
    setShowVenueDropdown(false)
  }

  // Get event type icon and color
  const getEventTypeIcon = (type: string) => {
    switch (type) {
      case 'game':
        return Users
      case 'practice':
        return Settings
      case 'tournament':
        return Trophy
      default:
        return Calendar
    }
  }

  const getEventTypeColor = (type: string) => {
    switch (type) {
      case 'game':
        return 'bg-blue-600 hover:bg-blue-700'
      case 'practice':
        return 'bg-green-600 hover:bg-green-700'
      case 'tournament':
        return 'bg-purple-600 hover:bg-purple-700'
      default:
        return 'bg-gray-600 hover:bg-gray-700'
    }
  }

  const EventTypeIcon = getEventTypeIcon(formData.event_type)

  const formContent = (
    <motion.form
      variants={containerVariants}
      initial="hidden"
      animate="visible"
      onSubmit={handleSubmit}
      className="space-y-6"
    >
      {/* Success Message */}
      {successMessage && (
        <motion.div variants={itemVariants}>
          <Alert className="border-green-200 bg-green-50">
            <Check className="h-4 w-4 text-green-600" />
            <AlertDescription className="text-green-800">
              {successMessage}
            </AlertDescription>
          </Alert>
        </motion.div>
      )}

      {/* Error Message */}
      {submitError && (
        <motion.div variants={itemVariants}>
          <Alert className="border-red-200 bg-red-50">
            <AlertTriangle className="h-4 w-4 text-red-600" />
            <AlertDescription className="text-red-800">
              {submitError}
            </AlertDescription>
          </Alert>
        </motion.div>
      )}

      {/* Basic Information */}
      <motion.div variants={itemVariants}>
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center">
              <Calendar className="h-5 w-5 mr-2 text-blue-600" />
              Event Information
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <label className="block text-sm font-medium text-gray-700">
                  Event Name *
                </label>
                <Input
                  value={formData.name}
                  onChange={(e) => setFormData(prev => ({ ...prev, name: e.target.value }))}
                  placeholder="Enter event name"
                  className={formErrors.name ? 'border-red-500 focus:border-red-500' : ''}
                />
                {formErrors.name && (
                  <p className="text-sm text-red-600 flex items-center">
                    <AlertTriangle className="h-4 w-4 mr-1" />
                    {formErrors.name}
                  </p>
                )}
              </div>

              <div className="space-y-2">
                <label className="block text-sm font-medium text-gray-700">
                  Event Type *
                </label>
                <select
                  value={formData.event_type}
                  onChange={(e) => setFormData(prev => ({
                    ...prev,
                    event_type: e.target.value as EventFormData['event_type']
                  }))}
                  className={`w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 ${
                    formErrors.event_type ? 'border-red-500' : 'border-gray-300'
                  }`}
                >
                  <option value="practice">Practice</option>
                  <option value="game">Game</option>
                  <option value="tournament">Tournament</option>
                </select>
                {formErrors.event_type && (
                  <p className="text-sm text-red-600 flex items-center">
                    <AlertTriangle className="h-4 w-4 mr-1" />
                    {formErrors.event_type}
                  </p>
                )}
              </div>
            </div>

            <div className="space-y-2">
              <label className="block text-sm font-medium text-gray-700">
                Description
              </label>
              <textarea
                value={formData.description}
                onChange={(e) => setFormData(prev => ({ ...prev, description: e.target.value }))}
                rows={3}
                placeholder="Enter event description (optional)"
                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none"
              />
            </div>
          </CardContent>
        </Card>
      </motion.div>

      {/* Schedule */}
      <motion.div variants={itemVariants}>
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center">
              <Clock className="h-5 w-5 mr-2 text-green-600" />
              Schedule
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                <label className="block text-sm font-medium text-gray-700">
                  Start Time *
                </label>
                <Input
                  type="datetime-local"
                  value={formData.start_time}
                  onChange={(e) => setFormData(prev => ({ ...prev, start_time: e.target.value }))}
                  className={formErrors.start_time ? 'border-red-500 focus:border-red-500' : ''}
                />
                {formErrors.start_time && (
                  <p className="text-sm text-red-600 flex items-center">
                    <AlertTriangle className="h-4 w-4 mr-1" />
                    {formErrors.start_time}
                  </p>
                )}
              </div>

              <div className="space-y-2">
                <label className="block text-sm font-medium text-gray-700">
                  End Time *
                </label>
                <Input
                  type="datetime-local"
                  value={formData.end_time}
                  onChange={(e) => setFormData(prev => ({ ...prev, end_time: e.target.value }))}
                  className={formErrors.end_time ? 'border-red-500 focus:border-red-500' : ''}
                />
                {formErrors.end_time && (
                  <p className="text-sm text-red-600 flex items-center">
                    <AlertTriangle className="h-4 w-4 mr-1" />
                    {formErrors.end_time}
                  </p>
                )}
              </div>
            </div>
          </CardContent>
        </Card>
      </motion.div>

      {/* Venue Selection */}
      <motion.div variants={itemVariants}>
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center">
              <MapPin className="h-5 w-5 mr-2 text-orange-600" />
              Venue
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-2">
              <label className="block text-sm font-medium text-gray-700">
                Search and Select Venue
              </label>
              <div className="relative">
                <div className="relative">
                  <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
                  <Input
                    value={venueSearch}
                    onChange={(e) => {
                      setVenueSearch(e.target.value)
                      setShowVenueDropdown(true)
                      if (!e.target.value) {
                        setFormData(prev => ({ ...prev, venue_id: '' }))
                      }
                    }}
                    onFocus={() => setShowVenueDropdown(true)}
                    placeholder="Search venues by name, city, or address..."
                    className="pl-10"
                  />
                  {formData.venue_id && (
                    <button
                      type="button"
                      onClick={() => {
                        setFormData(prev => ({ ...prev, venue_id: '' }))
                        setVenueSearch('')
                        setShowVenueDropdown(true)
                      }}
                      className="absolute right-3 top-1/2 transform -translate-y-1/2"
                    >
                      <X className="h-4 w-4 text-gray-400 hover:text-gray-600" />
                    </button>
                  )}
                </div>

                {/* Venue Dropdown */}
                {showVenueDropdown && venueSearch && (
                  <div className="absolute z-10 w-full mt-1 bg-white border border-gray-300 rounded-md shadow-lg max-h-60 overflow-y-auto">
                    {venuesLoading ? (
                      <div className="p-3 text-center text-gray-500">
                        <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-blue-600 mx-auto"></div>
                      </div>
                    ) : filteredVenues.length > 0 ? (
                      filteredVenues.map(venue => (
                        <div
                          key={venue.id}
                          onClick={() => handleVenueSelect(venue)}
                          className="p-3 hover:bg-gray-50 cursor-pointer border-b last:border-b-0"
                        >
                          <div className="font-medium text-gray-900">{venue.name}</div>
                          {venue.address && (
                            <div className="text-sm text-gray-500">
                              {venue.address}
                              {venue.city && `, ${venue.city}`}
                              {venue.state && `, ${venue.state}`}
                            </div>
                          )}
                          {venue.capacity && (
                            <div className="text-sm text-gray-500">
                              Capacity: {venue.capacity}
                            </div>
                          )}
                        </div>
                      ))
                    ) : (
                      <div className="p-3 text-center text-gray-500">
                        No venues found matching "{venueSearch}"
                      </div>
                    )}
                  </div>
                )}
              </div>

              {/* Selected venue display */}
              {formData.venue_id && (
                <div className="p-3 bg-green-50 border border-green-200 rounded-md">
                  <div className="flex items-center text-green-800">
                    <Check className="h-4 w-4 mr-2" />
                    <span className="font-medium">Venue selected: {venueSearch}</span>
                  </div>
                </div>
              )}
            </div>
          </CardContent>
        </Card>
      </motion.div>

      {/* Recurring Event */}
      <motion.div variants={itemVariants}>
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center">
              <Repeat className="h-5 w-5 mr-2 text-purple-600" />
              Recurrence
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div className="space-y-4">
              <label className="flex items-center space-x-2 cursor-pointer">
                <input
                  type="checkbox"
                  checked={formData.is_recurring}
                  onChange={(e) => setFormData(prev => ({
                    ...prev,
                    is_recurring: e.target.checked,
                    recurrence_rule: e.target.checked ? prev.recurrence_rule : ''
                  }))}
                  className="rounded border-gray-300 focus:ring-blue-500"
                />
                <span className="text-sm font-medium text-gray-700">
                  This is a recurring event
                </span>
              </label>

              {formData.is_recurring && (
                <div className="space-y-2 pl-6">
                  <label className="block text-sm font-medium text-gray-700">
                    Recurrence Pattern *
                  </label>
                  <select
                    value={formData.recurrence_rule}
                    onChange={(e) => setFormData(prev => ({ ...prev, recurrence_rule: e.target.value }))}
                    className={`w-full px-3 py-2 border rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 ${
                      formErrors.recurrence_rule ? 'border-red-500' : 'border-gray-300'
                    }`}
                  >
                    <option value="">Select recurrence pattern...</option>
                    <option value="DAILY">Daily</option>
                    <option value="WEEKLY">Weekly</option>
                    <option value="BIWEEKLY">Every 2 weeks</option>
                    <option value="MONTHLY">Monthly</option>
                  </select>
                  {formErrors.recurrence_rule && (
                    <p className="text-sm text-red-600 flex items-center">
                      <AlertTriangle className="h-4 w-4 mr-1" />
                      {formErrors.recurrence_rule}
                    </p>
                  )}
                </div>
              )}
            </div>
          </CardContent>
        </Card>
      </motion.div>

      {/* Form Actions */}
      <motion.div variants={itemVariants} className="flex justify-end space-x-4 pt-6">
        {onCancel && (
          <Button
            type="button"
            variant="outline"
            onClick={onCancel}
            disabled={submitting}
          >
            Cancel
          </Button>
        )}
        <Button
          type="submit"
          disabled={submitting || eventLoading}
          className={`${getEventTypeColor(formData.event_type)} text-white flex items-center`}
        >
          {submitting ? (
            <>
              <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
              {mode === 'create' ? 'Creating...' : 'Updating...'}
            </>
          ) : (
            <>
              <EventTypeIcon className="h-4 w-4 mr-2" />
              {mode === 'create' ? 'Create Event' : 'Update Event'}
            </>
          )}
        </Button>
      </motion.div>
    </motion.form>
  )

  // Handle click outside to close venue dropdown
  useEffect(() => {
    const handleClickOutside = () => setShowVenueDropdown(false)
    if (showVenueDropdown) {
      document.addEventListener('click', handleClickOutside)
      return () => document.removeEventListener('click', handleClickOutside)
    }
  }, [showVenueDropdown])

  if (isModal) {
    return (
      <Dialog open={true} onOpenChange={onCancel}>
        <DialogContent className="max-w-4xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <div className="flex items-center justify-center mb-4">
              <div className={`w-12 h-12 ${getEventTypeColor(formData.event_type)} rounded-full flex items-center justify-center shadow-lg`}>
                <EventTypeIcon className="w-6 h-6 text-white" />
              </div>
            </div>
            <DialogTitle className="text-center text-2xl font-bold">
              {mode === 'create' ? 'Create New Event' : 'Edit Event'}
            </DialogTitle>
            <DialogDescription className="text-center">
              {mode === 'create' ? 'Fill in the details to schedule a new event' : 'Update the event information'}
            </DialogDescription>
          </DialogHeader>

          {eventLoading ? (
            <div className="flex items-center justify-center py-8">
              <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
              <span className="ml-2 text-gray-600">Loading event...</span>
            </div>
          ) : (
            formContent
          )}
        </DialogContent>
      </Dialog>
    )
  }

  // Standalone page mode
  return (
    <div className="max-w-4xl mx-auto p-6">
      <div className="mb-6">
        <div className="flex items-center space-x-4 mb-4">
          <div className={`w-12 h-12 ${getEventTypeColor(formData.event_type)} rounded-full flex items-center justify-center shadow-lg`}>
            <EventTypeIcon className="w-6 h-6 text-white" />
          </div>
          <div>
            <h1 className="text-3xl font-bold text-gray-900">
              {mode === 'create' ? 'Create New Event' : 'Edit Event'}
            </h1>
            <p className="text-gray-600">
              {mode === 'create' ? 'Fill in the details to schedule a new event' : 'Update the event information'}
            </p>
          </div>
        </div>
      </div>

      {eventLoading ? (
        <div className="flex items-center justify-center py-8">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
          <span className="ml-2 text-gray-600">Loading event...</span>
        </div>
      ) : (
        formContent
      )}
    </div>
  )
}

import React, { useState, useEffect, useCallback } from 'react'
import { motion } from 'framer-motion'
import {
  Search,
  Plus,
  MapPin,
  Users,
  Edit3,
  Trash2,
  Eye,
  AlertTriangle,
  ChevronLeft,
  ChevronRight,
  Filter,
  ArrowUpDown,
  Building,
  Home,
  Map
} from 'lucide-react'
import { Button } from './ui/button'
import { Input } from './ui/input'
import { Card, CardContent, CardHeader, CardTitle } from './ui/card'
import { Alert, AlertDescription } from './ui/alert'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle
} from './ui/dialog'
import { useApi } from '../hooks/useApi'

interface Venue {
  id: string
  name: string
  address?: string
  city?: string
  state?: string
  zip_code?: string
  capacity?: number
  description?: string
  is_active?: boolean
  created_at: string
  updated_at: string
}

interface VenuesResponse {
  venues: Venue[]
  pagination: {
    page: number
    limit: number
    total: number
    pages: number
  }
}

interface VenueManagementProps {
  className?: string
  onCreateVenue?: () => void
  onEditVenue?: (venueId: string) => void
}

type SortField = 'name' | 'city' | 'capacity' | 'created_at'
type SortDirection = 'asc' | 'desc'

const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      staggerChildren: 0.1
    }
  }
}

const itemVariants = {
  hidden: { y: 20, opacity: 0 },
  visible: {
    y: 0,
    opacity: 1,
    transition: {
      duration: 0.3
    }
  }
}

export default function VenueManagement({
  className = '',
  onCreateVenue,
  onEditVenue
}: VenueManagementProps) {
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedVenue, setSelectedVenue] = useState<Venue | null>(null)
  const [showDetails, setShowDetails] = useState(false)
  const [showDeleteConfirm, setShowDeleteConfirm] = useState(false)
  const [venueToDelete, setVenueToDelete] = useState<string | null>(null)
  const [currentPage, setCurrentPage] = useState(1)
  const [pageSize] = useState(10)
  const [cityFilter, setCityFilter] = useState('')
  const [activeFilter, setActiveFilter] = useState<'all' | 'active' | 'inactive'>('all')
  const [sortField, setSortField] = useState<SortField>('name')
  const [sortDirection, setSortDirection] = useState<SortDirection>('asc')

  // API hooks
  const { data: venuesData, loading, error, execute: fetchVenues } = useApi<VenuesResponse>()
  const { loading: deleting, execute: deleteVenue } = useApi()

  // Fetch venues with current filters and pagination
  const loadVenues = useCallback(async () => {
    try {
      const params = new URLSearchParams({
        page: currentPage.toString(),
        limit: pageSize.toString()
      })

      if (cityFilter) {
        params.append('city', cityFilter)
      }

      if (activeFilter !== 'all') {
        params.append('is_active', (activeFilter === 'active').toString())
      }

      await fetchVenues(`/api/venues?${params}`)
    } catch (err) {
      console.error('Failed to load venues:', err)
    }
  }, [fetchVenues, currentPage, pageSize, cityFilter, activeFilter])

  // Load venues on mount and when filters change
  useEffect(() => {
    loadVenues()
  }, [loadVenues])

  // Filter and sort venues client-side for search functionality
  const filteredAndSortedVenues = React.useMemo(() => {
    let filtered = venuesData?.venues || []

    // Apply search filter
    if (searchQuery) {
      filtered = filtered.filter(venue =>
        venue.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        venue.address?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        venue.city?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        venue.description?.toLowerCase().includes(searchQuery.toLowerCase())
      )
    }

    // Apply sorting
    filtered.sort((a, b) => {
      let aValue: any = a[sortField]
      let bValue: any = b[sortField]

      // Handle null/undefined values
      if (aValue == null && bValue == null) return 0
      if (aValue == null) return sortDirection === 'asc' ? 1 : -1
      if (bValue == null) return sortDirection === 'asc' ? -1 : 1

      // Convert to strings for comparison if needed
      if (typeof aValue === 'string') aValue = aValue.toLowerCase()
      if (typeof bValue === 'string') bValue = bValue.toLowerCase()

      if (aValue < bValue) return sortDirection === 'asc' ? -1 : 1
      if (aValue > bValue) return sortDirection === 'asc' ? 1 : -1
      return 0
    })

    return filtered
  }, [venuesData?.venues, searchQuery, sortField, sortDirection])

  // Handle venue deletion
  const handleDeleteVenue = async () => {
    if (!venueToDelete) return

    try {
      await deleteVenue(`/api/venues/${venueToDelete}`, { method: 'DELETE' })
      setShowDeleteConfirm(false)
      setVenueToDelete(null)
      setShowDetails(false)
      setSelectedVenue(null)
      await loadVenues() // Refresh venue list
    } catch (err) {
      console.error('Failed to delete venue:', err)
    }
  }

  // Handle sorting
  const handleSort = (field: SortField) => {
    if (sortField === field) {
      setSortDirection(sortDirection === 'asc' ? 'desc' : 'asc')
    } else {
      setSortField(field)
      setSortDirection('asc')
    }
  }

  // Get unique cities for filter
  const availableCities = React.useMemo(() => {
    const cities = new Set<string>()
    venuesData?.venues?.forEach(venue => {
      if (venue.city) cities.add(venue.city)
    })
    return Array.from(cities).sort()
  }, [venuesData?.venues])

  // Handle view venue details
  const handleViewDetails = (venue: Venue) => {
    setSelectedVenue(venue)
    setShowDetails(true)
  }

  // Handle edit venue
  const handleEditVenue = (venueId: string) => {
    if (onEditVenue) {
      onEditVenue(venueId)
    }
    setShowDetails(false)
  }

  // Handle delete confirmation
  const handleDeleteClick = (venueId: string) => {
    setVenueToDelete(venueId)
    setShowDeleteConfirm(true)
  }

  // Pagination
  const totalPages = venuesData?.pagination?.pages || 1
  const canGoPrevious = currentPage > 1
  const canGoNext = currentPage < totalPages

  return (
    <motion.div
      variants={containerVariants}
      initial="hidden"
      animate="visible"
      className={`space-y-6 ${className}`}
    >
      {/* Header */}
      <motion.div variants={itemVariants}>
        <Card>
          <CardHeader>
            <div className="flex items-center justify-between">
              <div className="flex items-center space-x-3">
                <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center">
                  <Building className="h-5 w-5 text-white" />
                </div>
                <div>
                  <CardTitle className="text-2xl font-bold text-gray-900">
                    Venue Management
                  </CardTitle>
                  <p className="text-gray-600">Manage venue information and settings</p>
                </div>
              </div>
              <Button
                onClick={() => onCreateVenue && onCreateVenue()}
                className="bg-green-600 hover:bg-green-700 text-white"
              >
                <Plus className="h-4 w-4 mr-2" />
                Add Venue
              </Button>
            </div>
          </CardHeader>
        </Card>
      </motion.div>

      {/* Error Display */}
      {error && (
        <motion.div variants={itemVariants}>
          <Alert className="border-red-200 bg-red-50">
            <AlertTriangle className="h-4 w-4 text-red-600" />
            <AlertDescription className="text-red-800">
              {error}
            </AlertDescription>
          </Alert>
        </motion.div>
      )}

      {/* Filters and Search */}
      <motion.div variants={itemVariants}>
        <Card>
          <CardContent className="pt-6">
            <div className="flex flex-col md:flex-row gap-4 items-start md:items-center">
              {/* Search */}
              <div className="relative flex-1">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
                <Input
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Search venues by name, address, city, or description..."
                  className="pl-10"
                />
              </div>

              {/* City Filter */}
              <div className="w-full md:w-48">
                <select
                  value={cityFilter}
                  onChange={(e) => {
                    setCityFilter(e.target.value)
                    setCurrentPage(1)
                  }}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                >
                  <option value="">All Cities</option>
                  {availableCities.map(city => (
                    <option key={city} value={city}>{city}</option>
                  ))}
                </select>
              </div>

              {/* Active Filter */}
              <div className="w-full md:w-32">
                <select
                  value={activeFilter}
                  onChange={(e) => {
                    setActiveFilter(e.target.value as typeof activeFilter)
                    setCurrentPage(1)
                  }}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                >
                  <option value="all">All</option>
                  <option value="active">Active</option>
                  <option value="inactive">Inactive</option>
                </select>
              </div>
            </div>
          </CardContent>
        </Card>
      </motion.div>

      {/* Venue List */}
      <motion.div variants={itemVariants}>
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center">
              <Map className="h-5 w-5 mr-2 text-blue-600" />
              Venues ({venuesData?.pagination?.total || 0})
            </CardTitle>
          </CardHeader>
          <CardContent>
            {loading ? (
              <div className="flex items-center justify-center py-8">
                <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-blue-600"></div>
                <span className="ml-2 text-gray-600">Loading venues...</span>
              </div>
            ) : filteredAndSortedVenues.length > 0 ? (
              <div className="space-y-4">
                {/* Table Header */}
                <div className="grid grid-cols-12 gap-4 px-4 py-2 bg-gray-50 rounded-lg font-semibold text-sm text-gray-700">
                  <button
                    onClick={() => handleSort('name')}
                    className="col-span-3 flex items-center space-x-1 hover:text-blue-600 transition-colors text-left"
                  >
                    <span>Name</span>
                    <ArrowUpDown className="h-3 w-3" />
                  </button>
                  <div className="col-span-3">Address</div>
                  <button
                    onClick={() => handleSort('city')}
                    className="col-span-2 flex items-center space-x-1 hover:text-blue-600 transition-colors text-left"
                  >
                    <span>City</span>
                    <ArrowUpDown className="h-3 w-3" />
                  </button>
                  <button
                    onClick={() => handleSort('capacity')}
                    className="col-span-1 flex items-center space-x-1 hover:text-blue-600 transition-colors text-left"
                  >
                    <span>Capacity</span>
                    <ArrowUpDown className="h-3 w-3" />
                  </button>
                  <div className="col-span-1">Status</div>
                  <div className="col-span-2 text-right">Actions</div>
                </div>

                {/* Venue Rows */}
                {filteredAndSortedVenues.map((venue) => (
                  <div
                    key={venue.id}
                    className="grid grid-cols-12 gap-4 px-4 py-3 border border-gray-200 rounded-lg hover:shadow-md transition-all bg-white"
                  >
                    <div className="col-span-3">
                      <div className="font-semibold text-gray-900">{venue.name}</div>
                    </div>
                    <div className="col-span-3 text-sm text-gray-600">
                      {venue.address || 'No address'}
                    </div>
                    <div className="col-span-2 text-sm text-gray-600">
                      {venue.city || '-'}
                      {venue.state && `, ${venue.state}`}
                    </div>
                    <div className="col-span-1 text-sm text-gray-600 flex items-center">
                      {venue.capacity ? (
                        <>
                          <Users className="h-3 w-3 mr-1" />
                          {venue.capacity}
                        </>
                      ) : (
                        '-'
                      )}
                    </div>
                    <div className="col-span-1">
                      <span
                        className={`px-2 py-1 rounded-full text-xs font-medium ${
                          venue.is_active !== false
                            ? 'bg-green-100 text-green-800'
                            : 'bg-red-100 text-red-800'
                        }`}
                      >
                        {venue.is_active !== false ? 'Active' : 'Inactive'}
                      </span>
                    </div>
                    <div className="col-span-2 flex justify-end space-x-2">
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleViewDetails(venue)}
                      >
                        <Eye className="h-3 w-3" />
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleEditVenue(venue.id)}
                      >
                        <Edit3 className="h-3 w-3" />
                      </Button>
                      <Button
                        variant="outline"
                        size="sm"
                        onClick={() => handleDeleteClick(venue.id)}
                        className="text-red-600 hover:text-red-700 hover:border-red-300"
                      >
                        <Trash2 className="h-3 w-3" />
                      </Button>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="text-center py-8 text-gray-500">
                <Building className="h-12 w-12 mx-auto mb-3 text-gray-300" />
                <p className="text-lg font-medium">No venues found</p>
                <p className="text-sm">
                  {searchQuery || cityFilter || activeFilter !== 'all'
                    ? 'Try adjusting your search or filters'
                    : 'Create your first venue to get started'}
                </p>
                {!searchQuery && !cityFilter && activeFilter === 'all' && (
                  <Button
                    className="mt-4"
                    onClick={() => onCreateVenue && onCreateVenue()}
                  >
                    <Plus className="h-4 w-4 mr-2" />
                    Add Venue
                  </Button>
                )}
              </div>
            )}

            {/* Pagination */}
            {venuesData && venuesData.pagination.pages > 1 && (
              <div className="flex items-center justify-between mt-6 pt-4 border-t">
                <div className="text-sm text-gray-600">
                  Showing {venuesData.pagination.page} of {venuesData.pagination.pages} pages
                  ({venuesData.pagination.total} total venues)
                </div>
                <div className="flex items-center space-x-2">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setCurrentPage(currentPage - 1)}
                    disabled={!canGoPrevious}
                  >
                    <ChevronLeft className="h-4 w-4" />
                    Previous
                  </Button>
                  <span className="px-3 py-1 text-sm font-medium">
                    {currentPage}
                  </span>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={() => setCurrentPage(currentPage + 1)}
                    disabled={!canGoNext}
                  >
                    Next
                    <ChevronRight className="h-4 w-4" />
                  </Button>
                </div>
              </div>
            )}
          </CardContent>
        </Card>
      </motion.div>

      {/* Venue Details Modal */}
      <Dialog open={showDetails} onOpenChange={setShowDetails}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle className="flex items-center">
              <MapPin className="h-5 w-5 mr-2 text-blue-500" />
              Venue Details
            </DialogTitle>
          </DialogHeader>

          {selectedVenue && (
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <h3 className="text-lg font-semibold text-gray-900">{selectedVenue.name}</h3>
                  <div className="flex items-center mt-1">
                    <span
                      className={`px-2 py-1 rounded-full text-xs font-medium ${
                        selectedVenue.is_active !== false
                          ? 'bg-green-100 text-green-800'
                          : 'bg-red-100 text-red-800'
                      }`}
                    >
                      {selectedVenue.is_active !== false ? 'Active' : 'Inactive'}
                    </span>
                  </div>
                </div>
                {selectedVenue.capacity && (
                  <div className="text-right">
                    <div className="flex items-center justify-end">
                      <Users className="h-4 w-4 mr-2 text-gray-400" />
                      <span className="text-lg font-semibold">{selectedVenue.capacity}</span>
                    </div>
                    <div className="text-sm text-gray-500">Capacity</div>
                  </div>
                )}
              </div>

              {/* Address */}
              {(selectedVenue.address || selectedVenue.city) && (
                <div className="border-t pt-4">
                  <h4 className="font-medium text-gray-900 mb-2 flex items-center">
                    <Home className="h-4 w-4 mr-2 text-gray-400" />
                    Address
                  </h4>
                  <div className="text-gray-600">
                    {selectedVenue.address && (
                      <div>{selectedVenue.address}</div>
                    )}
                    {(selectedVenue.city || selectedVenue.state || selectedVenue.zip_code) && (
                      <div>
                        {selectedVenue.city}
                        {selectedVenue.state && `, ${selectedVenue.state}`}
                        {selectedVenue.zip_code && ` ${selectedVenue.zip_code}`}
                      </div>
                    )}
                  </div>
                </div>
              )}

              {/* Description */}
              {selectedVenue.description && (
                <div className="border-t pt-4">
                  <h4 className="font-medium text-gray-900 mb-2">Description</h4>
                  <p className="text-gray-600">{selectedVenue.description}</p>
                </div>
              )}

              {/* Metadata */}
              <div className="border-t pt-4 text-sm text-gray-500">
                <div>Created: {new Date(selectedVenue.created_at).toLocaleDateString()}</div>
                <div>Updated: {new Date(selectedVenue.updated_at).toLocaleDateString()}</div>
              </div>
            </div>
          )}

          <DialogFooter className="space-x-2">
            <Button
              variant="outline"
              onClick={() => setShowDetails(false)}
            >
              Close
            </Button>
            {selectedVenue && (
              <>
                <Button
                  variant="outline"
                  onClick={() => handleEditVenue(selectedVenue.id)}
                >
                  <Edit3 className="h-4 w-4 mr-2" />
                  Edit
                </Button>
                <Button
                  variant="destructive"
                  onClick={() => handleDeleteClick(selectedVenue.id)}
                >
                  <Trash2 className="h-4 w-4 mr-2" />
                  Delete
                </Button>
              </>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Delete Confirmation Modal */}
      <Dialog open={showDeleteConfirm} onOpenChange={setShowDeleteConfirm}>
        <DialogContent>
          <DialogHeader>
            <DialogTitle className="flex items-center">
              <AlertTriangle className="h-5 w-5 mr-2 text-red-500" />
              Confirm Deletion
            </DialogTitle>
            <DialogDescription>
              Are you sure you want to delete this venue? This action cannot be undone and may affect associated events.
            </DialogDescription>
          </DialogHeader>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={() => setShowDeleteConfirm(false)}
              disabled={deleting}
            >
              Cancel
            </Button>
            <Button
              variant="destructive"
              onClick={handleDeleteVenue}
              disabled={deleting}
            >
              {deleting ? (
                <>
                  <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white mr-2"></div>
                  Deleting...
                </>
              ) : (
                <>
                  <Trash2 className="h-4 w-4 mr-2" />
                  Delete Venue
                </>
              )}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </motion.div>
  )
}
